INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5994', 'spa', 'cosas profundas, asuntos ocultos o recónditos (arameo)', 'Este adjetivo arameo, empleado como sustantivo, aparece en la alabanza de Daniel tras la revelación del sueño de Nabucodonosor. El término designa aquello que es profundo, recóndito u oculto al entendimiento humano. Daniel contrasta la omnisciencia divina con las limitaciones humanas, afirmando que Dios revela misterios que exceden toda percepción natural. La palabra aparece en estado enfático, subrayando ''lo profundo'' como realidad concreta que Dios conoce y desvela.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5995', 'spa', 'gavilla, hilera de grano; hilera de grano segado tendida en el campo, lista para ser recogida o trillada', 'Término agrícola que designa el grano segado dispuesto en hileras o manojos en el campo, lo que llamamos gavillas. Aparece en contextos diversos: Amós lo emplea para el peso aplastante de un carro cargado, Jeremías para el grano que cae detrás del segador fuera del alcance del recolector, Miqueas para las gavillas llevadas a la era, y Zacarías para su inflamabilidad. Los cognados del hebreo misnaico y del siríaco se refieren a hierba o heno, lo que sugiere que el sentido fundamental es vegetación cortada tendida en el campo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5996', 'spa', 'Amisadai — líder danita cuyo nombre significa ''mi pariente es Shaddai''', 'Amisadai es el padre de Ahiezer, jefe de la tribu de Dan durante el periodo del desierto. El nombre es un compuesto teofórico que combina ''ammi'' (mi pariente) con ''Shaddai'' (el Todopoderoso), expresando la confesión de que Dios es tan cercano como la familia. Aparece exclusivamente en Números en contextos de censo, disposición del campamento y ofrendas tribales (Nm 1:12; 7:66-71; 10:25). La LXX lo transcribe como Αμ(ε)ισαδαι, preservando ambos elementos del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5997', 'spa', 'Prójimo, compañero, asociado; persona hacia quien se tienen obligaciones éticas y relacionales.', 'Siempre con sufijo posesivo, este sustantivo designa a una persona vinculada a otra por relación comunitaria o pactual. En Levítico funciona como término legal clave para el ''prójimo'' hacia quien el israelita debe honestidad, justicia y fidelidad (Lv 19:11, 15, 17). Alemán Nachbar, español prójimo y francés prochain convergen en este sentido de miembro de la misma comunidad. La única aparición fuera de Levítico — Zacarías 13:7, donde Dios llama al pastor herido ''mi compañero'' — revela una intimidad ausente en los contextos legales, sugiriendo una asociación que trasciende el deber cívico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5998', 'spa', 'Trabajar con fatiga, afanarse — esforzarse con agotamiento; especialmente en Eclesiastés para el esfuerzo extenuante de la vida humana.', 'El verbo עָמַל significa trabajar o afanarse con un matiz de cansancio y esfuerzo gravoso. Puede describir trabajo arduo ordinario (Sal 127:1, ''si el SEÑOR no edifica la casa, en vano trabajan los que la edifican''), pero su hogar teológico es Eclesiastés, donde se convierte en palabra clave para la búsqueda agotadora de sentido. Qohélet pregunta ''¿qué provecho tiene el que se afana?'' (Ecl 1:3) y concluye que todo trabajo bajo el sol es vanidad (Ecl 2:11, 19-21), aunque disfrutar del fruto del trabajo es don de Dios (Ecl 5:18). Jonás 4:10 lo usa para el esfuerzo que Jonás no invirtió en la planta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5999', 'spa', 'Trabajo, fatiga o miseria; labor agotadora, penalidad dolorosa o maldad maliciosa dirigida contra otros.', 'Trabajo, fatiga o miseria; labor agotadora, penalidad dolorosa o maldad maliciosa dirigida contra otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6000', 'spa', 'Amal, nombre propio de un descendiente de la tribu de Aser', 'Este nombre aparece una sola vez en los registros genealógicos de Aser en 1 Crónicas. La raíz hebrea עָמָל podría estar relacionada con ''labor'' o ''esfuerzo'', aunque como nombre propio funciona principalmente como identificador personal. El nombre figura entre los descendientes de Aser, preservado en la reconstrucción genealógica postexílica. Los testimonios de la Septuaginta muestran variaciones en su intento de transliterar este nombre poco conocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6001a', 'spa', 'trabajador, sufriente; quien labora o padece dificultades, usado para obreros y afligidos', 'Un término con doble matiz: el trabajador que se esfuerza y el sufriente que soporta la miseria. En Jueces 5:26 se refiere a obreros (en el contexto del manejo de la estaca de tienda), mientras que Job lo emplea dos veces para quienes padecen aflicción: los de alma amargada (3:20) y el miserable cuya riqueza se desvanece (20:22). Proverbios lo aplica al trabajador cuya hambre lo impulsa a laborar (16:26). El campo semántico abarca desde el neutro «obrero» hasta el empático «sufriente», unificados por la idea de quien carga un peso o soporta adversidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6001b', 'spa', 'que se afana, que trabaja — quien labora con esfuerzo agotador (solo en Eclesiastés)', 'Adjetivo verbal usado exclusivamente en Eclesiastés para describir a la persona dedicada a un trabajo penoso. Qohélet lo emplea para indagar la futilidad del esfuerzo humano: ¿qué gana el que se afana con todo su empeño (Ecl 3:9)? La palabra conlleva un matiz de cansancio ausente en términos neutros de trabajo. En Eclesiastés 2:18 y 9:9, el que se afana enfrenta la ironía de que el fruto de su labor pasa a manos de otro, subrayando la vanidad del esfuerzo bajo el sol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6002', 'spa', 'Amalec -- nieto de Esau; antepasado eponimo de los amalecitas, enemigos perennes de Israel', 'Amalec -- nieto de Esau; antepasado eponimo de los amalecitas, enemigos perennes de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6003', 'spa', 'Amalecita — adjetivo/sustantivo gentilicio para un miembro del pueblo amalecita, enemigos perennes de Israel.', 'El gentilicio עֲמָלֵקִי (Amaleqi) designa a un miembro de la nación amalecita, descendientes del nieto de Esaú, Amalec, que habitaban el Néguev y el desierto del Sinaí. Sirvieron como el enemigo arquetípico de Israel desde el desierto en adelante. El término aparece colectivamente con artículo para referirse a la nación junto a los cananeos que bloqueaban la entrada de Israel (Nm 14:25, 43, 45), en referencias geográficas como ''el campo de los amalecitas'' (Gn 14:7), y para individuos como el joven en las campañas de Saúl (1 S 15:6; 30:13). El español ''amalecita'' y el árabe ''عمالِقي'' conservan la forma gentilicia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6004', 'spa', 'Oscurecer, opacar, eclipsar; encubrir o ensombrecer', 'Este verbo denota oscurecimiento o pérdida de brillo, empleado tanto literal como metafóricamente. Lamentaciones 4:1 abre con una imagen impactante: «¡Cómo se ha oscurecido el oro!», metal precioso que pierde su lustre como metáfora de la gloria caída de Jerusalén. Ezequiel 28:3 lo usa con el sentido de «ocultar»: ningún secreto se le esconde al orgulloso príncipe de Tiro, dicho con ironía, pues él mismo es ciego a su propia vulnerabilidad. Ezequiel 31:8 afirma que los cedros del jardín del Edén «no lo igualaron» al gran árbol que representa al faraón: no podían eclipsar su esplendor. La raíz conecta con conceptos árabes de cubrir y encubrir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6005', 'spa', 'Emanuel; nombre simbólico que significa «Dios con nosotros», dado al niño-señal de la profecía de Isaías', 'El célebre nombre que significa «con nosotros está Dios», dado al niño de la profecía de Isaías al rey Acaz como señal de liberación divina. Isaías 7:14 introduce el nombre en el contexto de asegurar a Judá que la amenaza de Siria y Efraín fracasará antes de que el niño crezca. En 8:8 y 8:10, «Emanuel» se convierte en una declaración de confianza —«Dios está con nosotros»— que afirma la presencia divina protectora sobre Jerusalén frente a la invasión. El nombre funciona tanto como designación del niño-señal profético como fórmula confesional que expresa la certeza de la presencia protectora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6006', 'spa', 'Cargar o llevar una carga; soportar como peso (en voz activa y pasiva)', 'Verbo que abarca tanto la acción física de cargar bultos sobre animales como el estado pasivo de ser llevado. En Génesis 44:13 los hermanos de José cargan sus asnos con angustia; Nehemías 13:15 retrata a quienes violaban el sábado cargando asnos con vino y productos. El Salmo 68:20 transforma la imagen: Dios mismo «nos carga cada día con sus beneficios». Isaías 46:1-3 juega con ambas voces: los ídolos de Babilonia son «cargados» sobre bestias agotadas (pasiva), mientras que Israel ha sido «llevado» por Dios desde el vientre. El contraste entre la carga humana y el sustento divino constituye el peso teológico central de esta raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6007', 'spa', 'Amasías, oficial judío bajo el reinado de Josafat', 'Este nombre propio combina la raíz עָמַשׂ (llevar, cargar) con el elemento teofórico יָהּ (Yahvé), con el posible significado de ''Yahvé ha sostenido'' o ''Yahvé lleva''. Su portador fue un comandante militar que se ofreció voluntariamente al servicio de Yahvé durante el reinado de Josafat. El nombre sigue el patrón de otros nombres compuestos hebreos que expresan la acción o relación divina con el individuo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6008', 'spa', 'Amad, ciudad en el territorio tribal de Aser', 'Este topónimo aparece en la descripción de los límites de la herencia territorial de Aser. El nombre se conserva fonéticamente en las principales tradiciones de traducción, lo cual indica que se reconoce su función geográfica. BDB señala variantes textuales en los testimonios de la Septuaginta, lo que sugiere que el nombre resultaba desconocido para los traductores griegos posteriores, quienes lo transcribieron de maneras diversas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6009', 'spa', 'Ser profundo (Qal estativo); hacer profundo, profundizar o actuar de modo insondable (Hifil causativo)', 'Verbo cuyo sentido físico de profundidad se convierte en poderosa metáfora de extremos morales y espirituales. El único Qal estativo, en el Salmo 92:5, se asombra de que los pensamientos de Dios «son muy profundos», inescrutables para el necio. Las formas causativas del Hifil predominan, abarcando desde lo literal (Isaías 7:11: «pide señal profunda como el Seol») hasta lo siniestro: Isaías 29:15 condena a quienes «profundizan» para esconder sus planes del SEÑOR, y Oseas 5:2 acusa a Israel de haberse «hundido profundamente» en la corrupción. La profundidad física se transforma así en enredo moral: cuanto más se excava, más difícil es el retorno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6010', 'spa', 'עֵמֶק — un valle amplio o llanura baja entre colinas, frecuentemente escenario de batallas y asentamientos.', 'עֵמֶק — un valle amplio o llanura baja entre colinas, frecuentemente escenario de batallas y asentamientos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6011', 'spa', 'profundidad, la cualidad o extensión de lo que es profundo', 'Este sustantivo designa la profundidad como cualidad abstracta o dimensión espacial. En Proverbios 25:3, aparece en una comparación sobre las profundidades inescrutables del corazón de los reyes, en paralelo con la altura inconmensurable de los cielos y la tierra. La palabra enfatiza la naturaleza impenetrable e insondable de lo que se describe. La forma preposicional indica aquí propósito o referencia, sugiriendo que la profundidad del corazón real escapa a toda comprensión humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6012', 'spa', 'profundo, insondable; ininteligible u oscuro, referido al habla incomprensible', 'Adjetivo que significa profundo o insondable, empleado exclusivamente para el habla incomprensible en Isaías y Ezequiel. Isaías 33:19 describe a un pueblo feroz de «habla profunda», tan oscura que no se puede entender, probablemente refiriéndose a la lengua extranjera de los asirios. Ezequiel contrasta dos veces la misión de Israel con la de pueblos de «habla profunda y lengua difícil» (3:5-6), enfatizando que el idioma propio de Israel hace mayor su responsabilidad profética. El término evoca no solo una lengua extranjera sino un habla tan honda u oscura que resulta impenetrable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6013', 'spa', 'Profundo, ya sea en sentido físico/espacial (piel, agua, foso) o figuradamente de lo que es insondable e inescrutable. Adjetivo hebreo que transmite p', 'Profundo, ya sea en sentido físico/espacial (piel, agua, foso) o figuradamente de lo que es insondable e inescrutable. Adjetivo hebreo que transmite profundidad tanto en registros concretos como abstractos. En las leyes de examen sacerdotal de Levítico 13, aparece siete veces para describir infecciones cutáneas que penetran ''más profundas que la piel'' —una medición clínica y espacial que guía el diagnóstico del sacerdote. En otros pasajes se desplaza a terreno figurado: el consejo del corazón humano es ''aguas profundas'' (Pr 20:5), la sabiduría de Dios es ''más profunda que el Seol'' (Job 11:8), y las maquinaciones de los malvados son tan profundas que creen que Dios no puede descubrirlas (Sal 64:6). La evidencia multilingüe confirma esta división con claridad: las traducciones en alemán, español y francés usan vocabulario de profundidad espacial para Levítico, pero cambian a lenguaje abstracto de ''profundo'' para los textos sapienciales y poéticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6014a', 'spa', 'el que ata gavillas, un recolector durante la cosecha', 'Este participio Piel describe al trabajador agrícola que ata el grano cortado en gavillas para su transporte y almacenamiento. Aparece en el Salmo 129:7, en paralelo con «el segador», representando la actividad de la cosecha como metáfora referida a quienes maldecirían a Sión. El verbo denominativo deriva del sustantivo para gavilla, y el participio indica a aquel cuya acción característica es atar las espigas en manojos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6015', 'spa', 'lana (arameo), el pelo suave de la oveja', 'Esta palabra aramea para lana aparece en la visión de Daniel del Anciano de Días, cuyo cabello se describe como blanco cual lana limpia. El término es un préstamo léxico del arameo bíblico, cognado del hebreo צֶמֶר pero distinto de él. La comparación enfatiza la pureza y quizás la ancianidad o sabiduría mediante la imagen de la blancura. Se encuentran formas emparentadas atestiguadas en el arameo egipcio y en el mandeo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6016a', 'spa', 'Gavilla de grano cosechado; manojo atado de tallos cortados, central en la ley de la cosecha y el ritual de las primicias.', 'Sustantivo masculino que designa una gavilla, es decir, un manojo de tallos de grano cortados y atados durante la cosecha. A diferencia del homógrafo ómer (una medida de capacidad para áridos), esta palabra pertenece exclusivamente al ámbito agrícola. Su aparición más destacada se encuentra en la ceremonia de las primicias de Levítico 23:10-15, donde el sacerdote mece una gavilla ante el SEÑOR como acto inaugural de la siega. Deuteronomio 24:19 establece que la gavilla olvidada debe dejarse para el extranjero, la viuda y el huérfano. Rut 2:7, 15 retrata a Rut espigando entre las gavillas, y Job 24:10 la emplea figuradamente para referirse al alimento que cargan los oprimidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6016b', 'spa', 'Omer: medida de capacidad para áridos equivalente a la décima parte de un efa, usada exclusivamente en el relato del maná de Éxodo 16.', 'Unidad de medida para áridos que aparece únicamente en el relato del maná de Éxodo 16, donde funciona como la ración diaria que Dios prescribió para cada persona. El omer equivale a la décima parte de un efa (Exod 16:36), aproximadamente 2,3 litros. Cada israelita recogía un omer por cabeza (v. 16), y notablemente, ya recogieran mucho o poco, al medirlo resultaba exactamente un omer (v. 18). También se conservó un omer de maná en una vasija ante el Testimonio como memorial para las generaciones futuras (vv. 32–33). La Septuaginta lo transliteraba como gomor, y las traducciones modernas retienen el término hebreo como unidad técnica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6017', 'spa', 'Gomorra — ciudad destruida junto con Sodoma por juicio divino, sinónimo de ruina total. Nombre propio que designa a Gomorra, la antigua ciudad de la l', 'Gomorra — ciudad destruida junto con Sodoma por juicio divino, sinónimo de ruina total. Nombre propio que designa a Gomorra, la antigua ciudad de la llanura del Jordán destruida junto con Sodoma por fuego y azufre (Gn 19:24-28). En cada una de sus diecinueve apariciones figura emparejada con Sodoma, nunca sola, formando el dúo proverbial que se convirtió en la imagen bíblica principal de juicio divino catastrófico. Los profetas invocan el par como advertencia: ''como la destrucción de Sodoma y Gomorra'' se convierte en fórmula estándar para la devastación total (Is 13:19; Jer 49:18; 50:40; Am 4:11). Isaías incluso se dirige a los gobernantes de Jerusalén como ''gobernantes de Gomorra'' (Is 1:10), aplicando el topónimo metafóricamente a la corrupción moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6018', 'spa', 'Omri — nombre propio llevado por cuatro israelitas, más notablemente el sexto rey del reino del norte. Nombre propio hebreo que posiblemente significa', 'Omri — nombre propio llevado por cuatro israelitas, más notablemente el sexto rey del reino del norte. Nombre propio hebreo que posiblemente significa ''mi gavilla'' o ''discípulo de Yah''. De manera más prominente, Omri fue el poderoso rey de Israel que fundó Samaria como su nueva capital (1 Re 16:16-28). Tan duradera fue la reputación de su dinastía que los registros asirios continuaron llamando a Israel ''la casa de Omri'' (Bit-Humri) mucho después de que su linaje hubiera terminado. La Estela de Moab también lo menciona. Otros tres hombres llevan este nombre: un benjaminita (1 Cr 7:8), un judahíta (9:4) y un jefe de Isacar bajo David (27:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6019', 'spa', 'Amram; padre de Moisés, Aarón y Miriam, nieto de Leví y cabeza del clan amramita.', 'Nombre propio que probablemente significa ''el pariente es exaltado'' (de ''am + ram), designando a la figura más prominente en la genealogía levítica entre Leví y Moisés. Hijo de Coat y nieto de Leví, Amram se casó con Jocabed y fue padre de Aarón, Moisés y Miriam (Éx 6:18, 20; Nm 26:59). Su linaje ancla la línea sacerdotal levítica: los amramitas aparecen como clan reconocido en el censo del desierto y en las asignaciones de servicio del templo (Nm 3:19, 27; 1 Cr 26:23). Vivió 137 años según la fuente sacerdotal (Éx 6:20). Un segundo Amram aparece brevemente en Esdras 10:34 entre quienes tenían esposas extranjeras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6021', 'spa', 'Amasa — nombre propio, notablemente el comandante militar de Absalón, luego asesinado por Joab. Amasa es conocido principalmente como el sobrino de Da', 'Amasa — nombre propio, notablemente el comandante militar de Absalón, luego asesinado por Joab. Amasa es conocido principalmente como el sobrino de David a quien Absalón nombró comandante de su ejército rebelde (2 Sam 17:25). Tras la derrota de Absalón, David intentó la reconciliación ofreciendo a Amasa el mando de las fuerzas reales en lugar de Joab (2 Sam 19:13-14). Esta maniobra política terminó trágicamente cuando Joab asesinó a Amasa en Gabaón bajo el pretexto de saludarlo (2 Sam 20:9-10) —un crimen que David recordó en su lecho de muerte (1 Re 2:5, 32). Un Amasa distinto, un jefe efrateo, aparece brevemente en 2 Crónicas 28:12 abogando por la misericordia hacia los cautivos de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6022', 'spa', 'Amasai — nombre de varios israelitas: guerrero de David, levitas y un sacerdote.', 'Amasai es un nombre que llevan al menos cuatro individuos distintos en la Biblia hebrea. El más célebre es el guerrero que declaró su lealtad a David con un discurso inspirado por el Espíritu (1 Cr 12:19), posiblemente identificable con Abisai de 2 Sam 23:18. Otros portadores incluyen levitas en la genealogía coatita (1 Cr 6:25, 35), un sacerdote que tocó la trompeta ante el Arca (1 Cr 15:24) y un levita durante la reforma de Ezequías (2 Cr 29:12). El nombre probablemente deriva de la raíz עָמַס, «llevar, cargar».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6023', 'spa', 'Amasai, un sacerdote en la Jerusalén postexílica', 'Este nombre sacerdotal aparece en la lista de Nehemías entre quienes se establecieron en Jerusalén después del exilio. BDB lo señala como un probable error textual de un nombre similar que se encuentra en Crónicas, donde el pasaje paralelo presenta una forma ligeramente distinta. El nombre figura entre los sacerdotes que regresaron para servir en la comunidad restaurada del templo, dando testimonio de la continuidad del culto tras el destierro babilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6025', 'spa', 'Uva(s) — el fruto de la vid, usado colectivamente para el producto de la cosecha e individualmente para la baya. Sustantivo hebreo común para uva o uv', 'Uva(s) — el fruto de la vid, usado colectivamente para el producto de la cosecha e individualmente para la baya. Sustantivo hebreo común para uva o uvas, que abarca tanto la baya individual como la cosecha colectiva. Aparece en algunas de las imágenes agrícolas más vívidas de la Escritura: el copero del faraón sueña con exprimir uvas en una copa (Gn 40:10-11), los espías traen de regreso un enorme racimo de uvas de Canaán (Nm 13:23), y el Cántico de Moisés habla poéticamente de ''la sangre de la uva'' (Gn 49:11; Dt 32:14). La palabra también lleva peso teológico en la parábola de Isaías sobre la viña que produjo solo uvas silvestres (Is 5:2, 4) y en las ominosas ''uvas de veneno'' (Dt 32:32). El alemán distingue ''Traube'' (racimo) de ''Beeren'' (bayas), pero el hebreo usa este único término para ambos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6026', 'spa', 'Deleitarse, gozar con deleite exquisito; regocijarse en la bondad de Dios, vivir en lujo regalado o burlarse con placer.', 'En su esencia, este verbo designa un tipo de placer que roza la indulgencia, ya sea espiritual o sensual. En el Hitpael, la forma reflexiva invita al sujeto a «deleitarse en el SEÑOR» (Sal 37:4), prometiendo que ese gozo entregado será recompensado. Isaías 55:2 reitera la invitación: «deléitese vuestra alma en la abundancia». Sin embargo, la misma raíz puede deslizarse hacia la molicie: en Deuteronomio 28:56 describe a una mujer tan delicadamente criada que no posaría su pie en el suelo. Isaías 57:4 lleva el sentido aún más lejos, hacia la burla: «¿De quién os mofáis?» El cognado árabe ghanija (''comportarse con languidez amorosa'') insinúa el matiz sensual que la raíz siempre conlleva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6028', 'spa', 'Delicado, refinado; suave, acostumbrado al lujo y la comodidad', 'Este adjetivo describe a alguien refinado por el lujo, ablandado por la comodidad, habituado a la vida fácil. Deuteronomio 28 lo emplea dos veces en las maldiciones del pacto, retratando al hombre y a la mujer «delicados y tiernos» que se volverán salvajes durante el asedio, llegando incluso al canibalismo de sus propios hijos. El término aparece junto a «tierno» (רַךְ), enfatizando suavidad y sensibilidad. Isaías 47:1 se dirige a Babilonia personificada como «tierna y delicada», burlándose de su antiguo lujo antes de su degradación venidera. El vocablo sugiere tanto blandura física como la fragilidad psicológica de quien nunca ha enfrentado adversidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6030a', 'spa', 'habitarán/aullarán, verbo de significado incierto en Isaías 13:22', 'Esta palabra aparece en el oráculo de Isaías contra Babilonia, describiendo a chacales o criaturas salvajes. La raíz hebrea y su significado son objeto de debate: podría derivar de una raíz que significa «habitar» (según sugieren las consonantes) o «aullar/responder» (según la interpretación tradicional). El contexto describe ruinas desoladas habitadas por animales salvajes, lo cual apoya ambas lecturas. La concordancia de género del verbo con «chacales» resulta inusual, lo que ha suscitado discusión textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6030b', 'spa', 'Responder, contestar, replicar; también testificar o dar testimonio; en Nifal, ser respondido; ocasionalmente cantar antifonal.', 'עָנָה es el verbo hebreo estándar para la respuesta verbal, y con 314 apariciones está entretejido en prácticamente todo diálogo narrativo de la Biblia hebrea. La fórmula וַיַּעַן...וַיֹּאמֶר (''y respondió y dijo'') es uno de los patrones más reconocibles de la prosa bíblica, empleado cientos de veces para introducir discurso directo. Sin embargo, el verbo porta más que significado conversacional: en contextos legales se convierte en ''testificar''; el Decálogo usa precisamente este verbo para prohibir el falso testimonio (Éx 20:16). Un pequeño pero notable grupo apunta al canto responsorial (Os 2:15; Dt 31:21), donde describe una réplica antifonal o coral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6030c', 'spa', 'Cantar, entonar o responder con canto; usado para la adoración comunitaria, respuestas antifonales y exclamaciones de alabanza.', 'Distinguido del más común עָנָה (responder), este homónimo se especializa en la interpretación musical y vocal. Miriam dirige a las mujeres a ''cantar'' junto al Mar Rojo (Éx 15:21), las mujeres de Israel entonan antifonalmente sobre las victorias de Saúl y David (1 S 18:7), y los levitas responden con alabanza en la fundación del templo (Esd 3:11). El español alterna entre ''cantad'' y ''respondieron'', reflejando el solapamiento entre el canto y la llamada-y-respuesta litúrgica. La forma intensiva Piel sugiere alabanza deliberada y sostenida (Is 27:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6031a', 'spa', 'Estar ocupado, mantener atareado; participio Hifil que expresa las tareas que Dios da a la humanidad', 'Esta entrada representa un uso singular de una raíz (que normalmente significa «afligir») dentro del vocabulario propio de Qohélet. En Eclesiastés 1:13 y 3:10, el participio Hifil aparece en la frase «la ocupación que Dios ha dado a los hombres para que se ocupen en ella». Eclesiastés 5:19 emplea una forma relacionada: Dios «lo mantiene ocupado con el gozo de su corazón», dándole el contento como preocupación. El desarrollo semántico de «afligir» a «ocupar» puede involucrar la idea de cargar a alguien con actividad. Qohélet lo usa para describir la condición humana de incesante ajetreo, el ciclo interminable de tareas que llenan la existencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6031b', 'spa', 'Afligir, oprimir, humillar, abatir; violar (sexualmente); humillarse, ayunar; ser abatido, ser afligido; responder, contestar.', 'Afligir, oprimir, humillar, abatir; violar (sexualmente); humillarse, ayunar; ser abatido, ser afligido; responder, contestar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6032', 'spa', 'responder, contestar (arameo) — replicar verbalmente, siempre emparejado con ''y dijo'' en Daniel', 'responder, contestar (arameo) — replicar verbalmente, siempre emparejado con ''y dijo'' en Daniel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6033', 'spa', 'los pobres, los afligidos (plural arameo)', 'Este adjetivo arameo, empleado de forma sustantivada en plural, designa a quienes son pobres, necesitados o afligidos. Aparece en Daniel 4, donde el profeta aconseja a Nabucodonosor que muestre misericordia hacia los pobres. El término subraya la vulnerabilidad socioeconómica y la necesidad de compasión. Su forma refleja la morfología del plural arameo, distinta de la hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6034', 'spa', 'Aná — nombre propio horita/edomita; descubrió las fuentes termales en el desierto mientras apacentaba asnos.', 'Aná (עָנָה) es un nombre propio que aparece en las genealogías edomitas-horitas de Génesis 36. El portador más notable es el hijo de Zibeón que descubrió las fuentes termales en el desierto mientras pastoreaba asnos (Gn 36:24), un raro detalle biográfico en medio de una lista formularia. Este Aná es también padre de Oholibama, una de las esposas de Esaú (Gn 36:2, 14, 18, 25). Un segundo Aná aparece como hijo de Seir el horita (Gn 36:20, 29; 1 Cr 1:38, 40), posiblemente la misma figura desde una perspectiva genealógica distinta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6035', 'spa', 'Humilde, manso o apacible en disposición; también pobre, afligido o de baja condición socioeconómica', 'Humilde, manso o apacible en disposición; también pobre, afligido o de baja condición socioeconómica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6036', 'spa', 'Anub, nombre propio en la genealogía de Judá', 'Este nombre aparece una sola vez en los registros genealógicos de Judá en Crónicas. Su etimología es incierta, aunque la forma podría estar relacionada con raíces que sugieren fertilidad o productividad. Como ocurre con muchos nombres propios poco frecuentes en Crónicas, la Septuaginta muestra variaciones en los intentos de transliteración. El nombre funciona como identificador familiar dentro de los registros tribales de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6038', 'spa', 'humildad, mansedumbre; la cualidad de ser humilde o modesto, fundamento del temor al Señor', 'Sustantivo abstracto que denota humildad o mansedumbre, estrechamente vinculado al adjetivo ''humilde/manso.'' Proverbios presenta la humildad como el camino al honor: ''Antes del honor está la humildad'' (15:33, 18:12), y la asocia con el temor del Señor como fuente de riquezas, honra y vida (22:4). Sofonías exhorta a los humildes a ''buscar la humildad'' junto con la justicia como preparación para el día del Señor (2:3). El término representa una virtud bíblica esencial —lo opuesto al orgullo— caracterizada por una autovaloración apropiada ante Dios y ante los demás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6039', 'spa', 'humildad, aflicción; mansedumbre o abajamiento', 'Este sustantivo puede denotar tanto humildad o mansedumbre como virtud, o bien aflicción y sufrimiento como condición, según el contexto. En algunos pasajes describe la postura humilde del justo; en otros se refiere a la experiencia de ser afligido o abatido. Su rango semántico refleja la conexión en el pensamiento hebreo entre la humildad voluntaria y el sufrimiento involuntario. La forma constructa en el Salmo 22:24 presenta complejidad textual e interpretativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6040', 'spa', 'Aflicción, miseria o sufrimiento soportado por adversidad u opresión; en raras ocasiones, humildad o mansedumbre de espíritu', 'Aflicción, miseria o sufrimiento soportado por adversidad u opresión; en raras ocasiones, humildad o mansedumbre de espíritu');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6041', 'spa', 'Pobre, afligido, humilde; el que es materialmente indigente, oprimido en el sufrimiento o de espíritu manso ante Dios.', 'Pobre, afligido, humilde; el que es materialmente indigente, oprimido en el sufrimiento o de espíritu manso ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6042', 'spa', 'Uni, Uno; nombres propios levíticos de significado incierto, portados por músicos y servidores del templo', 'Nombre levítico que aparece en listas de músicos del templo y registros postexílicos. Primera de Crónicas menciona a Uni entre los levitas designados para el servicio musical con arpas y liras (15:18, 20). La lista de Nehemías de levitas que regresaron incluye a Uno (12:9), con una variante textual (Ketiv/Qere) que muestra ligeras diferencias ortográficas. Las variaciones de la LXX (Onei, Ionai, Ananías) sugieren incertidumbre en la transmisión. Son entradas genealógicas levíticas típicas que documentan al personal del templo, particularmente aquellos involucrados en la música de adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6044', 'spa', 'Anim, ciudad en la región montañosa de Judá', 'Este topónimo aparece en la lista de ciudades de Josué correspondientes a la región montañosa de Judá. BDB lo identifica posiblemente con Ghuwain, situada al oeste y al sur de Hebrón en las tierras altas centrales. El nombre se conserva fonéticamente en todas las traducciones, lo que indica su reconocida función como designación geográfica. La Septuaginta muestra variantes en los intentos de transliteración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6045', 'spa', 'Tarea, ocupación o quehacer gravoso; usado especialmente en Eclesiastés para el afán divinamente asignado.', 'Sustantivo masculino que significa tarea, ocupación o quehacer, y que aparece casi exclusivamente en Eclesiastés con un matiz marcadamente pesado. Qohélet lo emplea para describir la ocupación fatigosa que Dios ha dado a la humanidad (Ecl 1:13, 3:10), el afán inquieto que llena los días del hombre de dolor (Ecl 2:23, 26) y el trabajo solitario sin satisfacción (Ecl 4:8, 5:3, 8:16). Posiblemente un préstamo del arameo relacionado con el siríaco ''ocuparse de'', el término captura la paradoja de una actividad humana con propósito pero finalmente frustrante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6046', 'spa', 'Anem, ciudad levítica (variante ortográfica de En-ganim)', 'Este nombre aparece en Crónicas como una ciudad levítica, aunque BDB lo señala como un error textual por En-ganim («fuente de jardines»), que figura en el pasaje paralelo de Josué. El nombre probablemente surgió por confusión escribal, al perderse el elemento inicial «En». La ubicación pretendida es probablemente Yenín, una ciudad importante en la parte septentrional del territorio de Isacar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6049b', 'spa', 'Practicar adivinación, agorerismo o hechicería; práctica ocultista prohibida asociada con las naciones paganas.', 'Forma verbal Poel que denota la práctica de la adivinación o el agorerismo, condenada de manera consistente en la legislación israelita. Levítico 19:26 la prohíbe junto con otras prácticas ocultistas, y Deuteronomio 18:10-14 incluye al meʿonen (''agorero'') entre las abominaciones de las naciones cananeas que Israel no debe imitar. La etimología del término sigue siendo debatida: posiblemente conectada con ʿayin (''ojo'', sugiriendo observación de presagios) o con una raíz árabe que significa ''zumbido nasal'' (sugiriendo encantamiento). Tanto Manasés (2 R 21:6; 2 Cr 33:6) como las naciones circundantes de Israel son condenados por esta práctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6051', 'spa', 'Nube — masa visible en el cielo; especialmente la nube teofánica de la presencia protectora y guiadora de Dios.', 'Nube — masa visible en el cielo; especialmente la nube teofánica de la presencia protectora y guiadora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6056', 'spa', 'rama, ramaje; las ramas extendidas de un árbol, especialmente en la visión de Daniel', 'Palabra aramea para ramas o ramaje de un árbol, que aparece exclusivamente en la visión de Daniel sobre el sueño del árbol de Nabucodonosor (capítulo 4). Las ramas del gran árbol proporcionan refugio a las aves y sombra a las bestias, simbolizando el dominio mundial del emperador. Cuando el árbol es cortado, las ramas son despojadas, representando la pérdida de reino y autoridad. La cuádruple repetición en Daniel 4 (versículos 12, 14 dos veces y 21) enfatiza tanto la gloria inicial del árbol —ramas que cobijan a todas las criaturas— como su juicio, cuando las ramas son arrancadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6057', 'spa', 'Rama, ramaje; extremidad de un árbol o vid, usado literal y figuradamente en la imaginería profética de crecimiento y juicio.', 'Este sustantivo designa una rama o ramaje de un árbol, utilizado tanto en instrucciones agrícolas cotidianas como en un rico simbolismo profético. Levítico 23:40 prescribe tomar ramas de árboles frondosos para la Fiesta de los Tabernáculos. Ezequiel emplea la palabra con gran fuerza en su alegoría del cedro (Ez 17:23) y de la vid (Ez 17:8), así como en la promesa de que las ramas de Israel volverán a dar fruto (Ez 36:8). El último capítulo de Malaquías advierte que el día venidero no dejará a los impíos ni raíz ni rama (Mal 3:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6059', 'spa', 'Engalanar con collar, adornar; metafóricamente, colmar generosamente de dones', 'Este verbo denominativo deriva del sustantivo «collar» y significa poner un collar a alguien o funcionar como collar. Salmo 73:6 dice que «la soberbia les sirve de collar», una vívida metáfora de cómo los impíos llevan la arrogancia como adorno visible. Deuteronomio 15:14 emplea el infinitivo absoluto Hifil para enfatizar: «ciertamente lo proveerás», es decir, cárgalo liberalmente con regalos del rebaño, la era y el lagar al liberar a un siervo hebreo. El doble infinitivo intensifica el mandato: provee abundantemente, hazle un rico collar de provisiones. La extensión metafórica del adorno físico a la generosa provisión muestra la concretez imaginativa del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6060b', 'spa', 'Collar, pendiente de cuello; joyería ornamental que se lleva alrededor del cuello', 'Este sustantivo denota un collar o pendiente de cuello, considerado un aramaísmo en el hebreo bíblico. Aparece como joyería en diferentes contextos: adornos de camellos en Jueces 8:26, parte del atavío de un joven en Proverbios 1:9, y como imagen poética en Cantares 4:9 donde una sola gema del collar de la novia cautiva el corazón del amante. Las formas plurales sugieren múltiples pendientes o cadenas que forman collares elaborados. En Jueces, las cadenas tomadas de los camellos madianitas representan un botín valioso. Proverbios lo usa figuradamente: la enseñanza de la sabiduría será un collar elegante que adorna al joven. El uso en Cantares es intensamente personal, enfocándose en la belleza de un solo pendiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6061', 'spa', 'Anac, antepasado epónimo de los anaceos, una raza de guerreros de gran estatura que habitaba Canaán antes de la conquista israelita.', 'Se refiere a Anac (עֲנָק), cuyo nombre probablemente deriva de la raíz hebrea para «cuello» o «collar», sugiriendo quizá la «gran estatura» o el porte imponente de sus descendientes. Es presentado como el ancestro de los temibles anaceos, habitantes gigantes de la región de Hebrón cuya talla aterró a los espías israelitas (Nm 13:22, 28, 33). Josué 15:13 identifica a Arba como «el padre de Anac», situándolo en una genealogía que ancla la tradición de los gigantes en la geografía específica de Hebrón. El nombre aparece con artículo definido («el Anac») en varios pasajes, lo que sugiere que pudo funcionar originalmente como designación de clan más que como nombre personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6062', 'spa', 'Anaceos, raza de gigantes descendientes de Anac que habitaron Canaán, especialmente la región de Hebrón, antes de la conquista israelita.', 'Forma plural que designa a los anaceos (עֲנָקִים), el legendario pueblo de gran estatura al que se enfrentaron los espías israelitas en Canaán. Su imponente tamaño hizo que los espías se sintieran «como langostas» en comparación (Nm 13:33), y su fama convirtió la conquista en algo aparentemente imposible para la generación incrédula. Deuteronomio registra cuidadosamente que los emitas, los zomzomeos y los anaceos eran todos considerados gigantes (Dt 2:10-11, 21), pero fueron desplazados por otras naciones como precedente de lo que Israel podía lograr. La Septuaginta los transcribe como Ενακειμ, reflejando fielmente el plural hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6063', 'spa', 'Aner; tanto un nombre personal (aliado de Abraham) como una ciudad en Manasés asignada a los levitas', 'Aner aparece tanto como persona como lugar. En Génesis 14, Aner es uno de los tres aliados amorreos de Abraham que se unieron a su campaña para rescatar a Lot de los reyes orientales. Junto con Escol y Mamre, Aner representa las relaciones de pacto que Abraham mantuvo con líderes cananeos locales. Como topónimo, Aner fue una ciudad levítica en Manasés, asignada a los levitas coatitas según 1 Crónicas 6:70. El uso dual—personal y geográfico—es común en la onomástica bíblica, donde individuos y asentamientos comparten nombres. El significado etimológico de Aner es incierto, aunque se han propuesto varias conexiones semíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6064', 'spa', 'Multar o imponer una pena pecuniaria; en sentido amplio, castigar; en Nifal, ser multado o sufrir castigo.', 'Verbo jurídico arraigado en el tribunal y el mercado, que originalmente denota la imposición de una multa económica. Deuteronomio 22:19 prescribe que al marido calumniador «le multarán con cien siclos de plata», y 2 Crónicas 36:3 relata que el faraón Necó multó a la tierra de Judá. En los contextos legales concretos se emplea «multar»; en los dichos sapienciales de Proverbios (17:26; 21:11) se amplía a «castigar». El Nifal pasivo —«ser multado, castigado»— aparece en Éxodo 21:22 con la construcción enfática del infinitivo absoluto («ciertamente será multado») y en Proverbios 22:3 y 27:12, donde los ingenuos siguen adelante y «son castigados».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6068', 'spa', 'Anatot, ciudad levítica en Benjamín; lugar de origen de Jeremías y de destierro de Abiatar.', 'ʿAnātôt designa una ciudad levítica en el territorio tribal de Benjamín, situada a unos cinco kilómetros al nor-noreste de Jerusalén, en la actual ʿAnātā. Aparece por primera vez como asignación levítica (Jos 21:18) y cobra importancia cuando Salomón destierra allí al sacerdote Abiatar (1 Re 2:26). Su mayor fama proviene de ser la patria de Jeremías, cuyos propios paisanos conspiraron contra él (Jer 1:1; 11:21–23). La compra de un campo en Anatot durante el asedio de Jerusalén se convierte en señal profética de restauración futura (Jer 32:7–9). Se cuentan repatriados de esta ciudad entre los que regresaron del exilio (Esd 2:23; Neh 7:27; 11:32). El nombre podría evocar a la diosa cananea Anat.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6069', 'spa', 'Anatotita — gentilicio de Anatot, que designa a una persona oriunda de esa ciudad benjaminita.', 'Adjetivo gentilicio que identifica a alguien como natural de Anatot, la ciudad benjaminita situada a unos cinco kilómetros al noreste de Jerusalén. Esta designación se aplica a guerreros de la guardia de élite de David — Abiezer (2 Sam 23:27; 1 Cr 11:28; 27:12) y Jehú (1 Cr 12:3) — y al propio Jeremías en la referencia burlona de Jer 29:27. El artículo lo precede regularmente: «el anatotita». Tanto en español como en alemán se reproduce este patrón de gentilicio articulado: «el anatotita», «der Anathothite».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6071', 'spa', 'Mosto, jugo dulce recién exprimido — zumo de uva o fruta recién extraído.', 'Designa el jugo dulce recién prensado, el vino en su etapa más temprana y potente antes de la fermentación completa. Los profetas lo emplean para pintar imágenes vívidas: montañas que destilan mosto en la era mesiánica (Jl 3:18; Am 9:13) y los enemigos de Israel obligados a beber su propia sangre «como mosto» (Is 49:26). En Cnt 8:2 aparece como «jugo de mi granada», extendiendo el término más allá de la uva. Joel 1:5 lamenta su pérdida como señal de juicio devastador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6073', 'spa', 'ramas, ramos; follaje', 'Este sustantivo designa las ramas o el follaje de los árboles, y aparece en la poesía sobre la creación en el Salmo 104. Se reconoce como un préstamo del arameo, con cognados que significan follaje o flores en dialectos arameos. El Ketiv y el Qere muestran variación textual en la forma, aunque ambos apuntan a una imagen de vegetación. La palabra evoca el hábitat donde las aves moran entre las ramas, cantando desde la copa de los árboles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6074', 'spa', 'Follaje; las hojas de un árbol colectivamente', 'Este sustantivo arameo aparece solo en Daniel 4, describiendo el follaje del gran árbol en el sueño de Nabucodonosor. El follaje ''hermoso'' o ''bello'' del árbol se menciona tres veces como parte de la descripción del árbol—sus hojas son exuberantes, proporcionando sombra a las bestias y refugio a las aves, simbolizando el vasto imperio del rey que da sustento y protección. La destrucción del árbol incluye el despojamiento de su follaje. La palabra enfatiza el dosel vivificante del árbol, la abundancia verde que lo hace beneficioso para las criaturas. En la interpretación del sueño, el follaje representa la extensión y beneficencia del dominio del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6075a', 'spa', 'estar hinchado, inflado; ser arrogante, engreído', 'Este verbo, que aparece en la conjugación Pual (pasiva), significa estar hinchado o inflado, con una connotación moral de arrogancia u orgullo. En Habacuc 2:4 describe el alma del impío como hinchada o arrogante, en contraste con el justo que vive por su fidelidad. La raíz puede relacionarse con la hinchazón física, extendida metafóricamente para describir la inflación moral. El texto y su interpretación presentan dificultades, y algunos eruditos proponen enmiendas textuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6075b', 'spa', 'actuar presuntuosamente, proceder con temeridad; mostrar imprudencia', 'Este verbo en la conjugación Hifil describe actuar con presunción, temeridad o imprudencia. En Números 14:44 caracteriza el intento temerario de Israel de entrar en la tierra a pesar de la prohibición divina, después de haber rechazado el mandato inicial de Dios. El verbo capta la inversión insensata: avanzar presuntuosamente tras haber perdido el momento de obediencia. BDB sugiere «mostraron descuido», mientras otros proponen «presumieron», ambos enfatizando la naturaleza temeraria y no autorizada de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6076a', 'spa', 'Montículo, colina, elevación fortificada; específicamente la acrópolis o ciudadela dentro de una ciudad', 'Este sustantivo denota un montículo o colina fortificada, típicamente refiriéndose a la ciudadela o acrópolis dentro de una ciudad. En Jerusalén, designaba un área fortificada específica en el extremo sur de la colina oriental, el Ofel. Nehemías 3:26-27 lo menciona como un distrito donde vivían los servidores del templo, con su propio muro. 2 Crónicas 27:3 y 33:14 registran proyectos de construcción en el muro del Ofel de Jerusalén. Isaías 32:14 lo usa en una profecía de desolación: la colina y la torre de vigilancia se convertirán en guaridas para siempre. Miqueas 4:8 se dirige al ''Ofel de la hija de Sion'', aparentemente refiriéndose a la colina de la ciudadela como representativa de la ciudad. El término también podía aplicarse al montículo fortificado de Samaria (2 Reyes 5:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6076b', 'spa', 'Tumores, hemorroides — hinchazones infligidas a los filisteos como plaga divina.', 'Se refiere a hinchazones dolorosas o hemorroides infligidas como plaga divina. La palabra aparece únicamente en el relato de la cautividad del Arca entre los filisteos (1 Sam 5-6) y en las maldiciones del pacto de Dt 28:27. El Ketiv masorético lee עֳפָלִים mientras que el Qeré sustituye el eufemístico טְחֹרִים, reflejando la sensibilidad escribal respecto a la dolencia. Las réplicas de oro de estos tumores que los filisteos ofrecieron como ofrenda por la culpa (1 Sam 6:4-5) subrayan la gravedad tanto corporal como teológica de la plaga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6077', 'spa', 'Ofel — el montículo fortificado o espolón dentro de Jerusalén (y Samaria).', 'Designa un montículo fortificado o acrópolis, usado casi exclusivamente para el espolón meridional de la colina oriental de Jerusalén. Miqueas 4:8 lo interpela como «torre del rebaño, Ofel de la hija de Sion», vinculándolo con la autoridad real. Nehemías registra reparaciones en el muro del Ofel (Neh 3:26-27), mientras que Crónicas menciona proyectos de fortificación de Jotam y Manasés (2 Cr 27:3; 33:14). En 2 Re 5:24, el término podría referirse a un montículo-ciudadela similar en Samaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6078', 'spa', 'Ofni, una ciudad en el territorio de Benjamín', 'Este topónimo aparece con el artículo definido en la lista de ciudades benjaminitas de Josué. La ubicación exacta es incierta, aunque el nombre se preserva en transliteraciones griegas. El artículo sugiere «la Ofni», quizás indicando un punto de referencia o asentamiento bien conocido. La ciudad pertenecía a la herencia de Benjamín en las tierras altas centrales de Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6079', 'spa', 'Párpado; usado poéticamente para los ojos en general, y figuradamente para los primeros rayos del alba.', 'Se refiere a los párpados, apareciendo casi siempre en forma dual como paralelo de ''ojos''. La palabra abarca un vívido abanico de imágenes: párpados cerrados en el sueño (Sal 132:4), llanto (Jer 9:18), mirada seductora (Pr 6:25) y la mirada penetrante de Dios que escudriña a la humanidad (Sal 11:4). Quizás la imagen más memorable es la de Job al hablar de «los párpados del alba» (Job 3:9; 41:18), una metáfora impactante donde las primeras franjas de luz al amanecer se representan como un ojo que se abre lentamente. Las glosas en español (''párpados'') y en francés (''paupière'') confirman uniformemente el sentido concreto de párpado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6080', 'spa', 'arrojar polvo, lanzar tierra contra alguien', 'Este verbo denominativo en Piel significa cubrir de polvo a alguien o arrojarle tierra. Aparece en el relato de Simei maldiciendo a David, donde Simei no solo maldijo verbalmente sino que también le arrojaba polvo y piedras continuamente. El verbo deriva del sustantivo para polvo o tierra e indica una acción agresiva, combinándose con el acusativo cognado para dar énfasis: «arrojaba polvo con polvo», intensificando la expresión de desprecio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6081', 'spa', 'Efer; nombre propio que significa ''cervatillo'' o ''becerro,'' portado por descendientes de Madián, Judá y Manasés', 'Nombre propio que aparece en genealogías de tres líneas tribales distintas. Génesis 25:4 y su paralelo en 1 Crónicas 1:33 identifican a Efer como hijo de Madián (hijo de Abraham por medio de Cetura), lo que lo convierte en nieto de Abraham. En la genealogía de Judá (1 Cr 4:17), aparece otro Efer entre los descendientes. Una tercera mención ocurre en la genealogía de Manasés (1 Cr 5:24) entre los jefes de familias. Las transliteraciones de la LXX varían (Gofer, Gafer, Afer), algo típico en nombres propios. El nombre probablemente deriva de una raíz que significa ''cervatillo'' o ''becerro,'' frecuente en la onomástica semítica antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6082', 'spa', 'cervatillo, ciervo joven — cría de ciervo o gacela, usado en la imaginería pastoral del Cantar de los Cantares', 'Sustantivo que designa un ciervo joven o cervatillo, presente exclusivamente en el Cantar de los Cantares como parte de su rica imaginería pastoral. El amado es comparado con un cervatillo que salta por los montes (Cnt 2:9, 17; 8:14), mientras que la belleza de la mujer se asemeja a dos crías gemelas de gacela (Cnt 4:5; 7:3). La expresión constructa עֹפֶר הָאַיָּלִים (cervatillo de los ciervos) se empareja con צְבִי (gacela) a lo largo del libro, creando una doble imagen de gracia y vitalidad juvenil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6083', 'spa', 'Polvo, tierra seca o suelo suelto; materia de la creación y mortalidad humana; también escombro o polvo fino.', 'עָפָר es la tierra seca y suelta de la que fue formada la humanidad (Gn 2:7) y a la que todo retorna (Gn 3:19). Es el polvo que se arroja sobre la cabeza en señal de duelo (Jos 7:6; Job 2:12), el suelo que absorbe la sangre (Is 34:7), la tierra que la serpiente debe comer en su humillación (Gn 3:14) y las innumerables partículas con las que Abraham compara a su descendencia prometida (Gn 13:16). Su peso teológico es inmenso: עָפָר es a la vez la materia prima de la creación y el emblema de la mortalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6084', 'spa', 'Ofrá, nombre propio de ciudades en Manasés (hogar de Gedeón) y Benjamín.', 'Nombre propio masculino que designa al menos dos ciudades israelitas. La Ofrá más prominente es la ciudad natal de Gedeón en el territorio de Manasés, donde el ángel del SEÑOR se le apareció bajo la encina (Jue 6:11), donde edificó un altar llamado ''El SEÑOR es paz'' (Jue 6:24) y donde fue sepultado (Jue 8:32). Trágicamente, fue también el lugar donde Gedeón erigió el efod que se convirtió en trampa para Israel (Jue 8:27). Una segunda Ofrá en Benjamín figura entre las ciudades asignadas a esa tribu (Jos 18:23) y aparece en las narrativas de las guerras filisteas (1 Sam 13:17). El nombre podría derivar de una raíz que significa ''polvo'' o ''cervatillo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6085', 'spa', 'Efrón — propietario hitita en Hebrón; también una ciudad cerca de Betel tomada por Abías.', 'Este nombre propio identifica dos referentes bíblicos distintos. El principal es Efrón el hitita, el terrateniente de quien Abraham compró la cueva de Macpela como sepultura para Sara (Génesis 23). La elaborada negociación entre Abraham y Efrón ante los hijos de Het constituye una de las transacciones comerciales más detalladas de la Biblia. El segundo referente es una ciudad mencionada en 2 Crónicas 13:19, a veces vocalizada como Efraín, que el rey Abías de Judá capturó de Jeroboam junto con Betel y Jesaná.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6086', 'spa', 'Árbol, madera, leña; palo, estaca/madero de ejecución, asta de arma; término amplio para toda planta o producto leñoso.', 'El hebreo עֵץ es la palabra universal para todo lo leñoso: desde un árbol vivo en un huerto hasta una tabla de construcción o un haz de leña. Su prominencia teológica comienza en el Edén con el ''árbol de la vida'' y el ''árbol del conocimiento del bien y del mal'' (Gn 2:9), y se mantiene en Proverbios, donde ''árbol de vida'' se convierte en metáfora de sabiduría y prosperidad (Pr 3:18). Materialmente, עֵץ es la madera de acacia del tabernáculo (Éx 25:10), la leña que Abraham ata para Isaac (Gn 22:3) y el madero que Amán construye para Mardoqueo (Est 5:14). Su amplitud semántica abarca simultáneamente planta, material y producto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6087a', 'spa', 'Herir, doler o afligir; emocionalmente entristecerse, en causativo agraviar a otro, y físicamente lastimar o torcer.', 'Un verbo de sentimiento profundo que abarca desde el dolor interior hasta el daño exterior. En su uso más frecuente describe la aflicción que Dios sintió por la maldad humana (Gn 6:6) o la angustia de quienes presencian una injusticia (Gn 34:7). Las formas Piel e Hifil dirigen el dolor hacia fuera: entristecer o provocar a alguien, como cuando Israel contristó al Espíritu Santo (Is 63:10). El español distingue consistentemente los sentidos emocionales con «entristecer» y reserva «lastimar» para el sentido físico de Ecl 10:9, confirmando que los hablantes de hebreo diferenciaban la aflicción emocional del daño corporal bajo una misma raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6088', 'spa', 'adolorido, angustiado; afligido (arameo)', 'Este adjetivo arameo, empleado como participio pasivo, describe un estado de dolor, aflicción o angustia emocional. En Daniel 6:20 califica la voz de Darío, quien llamó a Daniel con un tono adolorido y angustiado. El término transmite la intensidad del sufrimiento interior del rey ante la incertidumbre sobre el destino de Daniel en el foso de los leones. Como forma aramea, guarda relación con cognados hebreos que expresan dolor y pesar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6089a', 'spa', 'Dolor, pena, sufrimiento; trabajo penoso, afan — padecimiento físico o emocional, o la carga del esfuerzo laborioso.', 'El sustantivo עֶצֶב reúne bajo una misma raíz las experiencias aparentemente dispares del dolor y el trabajo penoso, vinculando el sufrimiento con el esfuerzo arduo. En Gen 3:16, Dios anuncia a Eva que su alumbramiento conllevará dolor (עֶצֶב), ligando la palabra a la maldición primordial. La literatura sapiencial, sin embargo, desarrolla la dimensión del afán: «en todo trabajo hay provecho» (Prov 14:23), y el salmista advierte contra «el pan del trabajo ansioso» (Sal 127:2). Ambos sentidos convergen en la percepción de que el trabajo en un mundo caído es inherentemente doloroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6089b', 'spa', 'vasija, utensilio; objeto moldeado', 'Este sustantivo designa una vasija u objeto fabricado, con énfasis en su carácter de pieza formada o moldeada por manos humanas. En Jeremías 22:28 aparece en una pregunta retórica sobre Conías (Joaquín): ¿acaso es una vasija despreciada y rota? El término subraya la naturaleza artesanal de la cerámica, extendida metafóricamente a una persona vista como un cacharro desechado. El BDB lo distingue del homónimo que significa ''dolor'' pese a su grafía idéntica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6090a', 'spa', 'Dolor, sufrimiento; aflicción y angustia, ya sea física o emocional', 'Este sustantivo denota dolor y sufrimiento, particularmente el dolor del parto o la angustia. En 1 Crónicas 4:9, Jabes recibe su nombre porque su madre lo dio a luz ''con dolor'', posiblemente haciendo referencia a un trabajo de parto difícil. Salmo 139:24 habla del ''camino doloroso'', cualquier senda de maldad que causa dolor o conduce a la destrucción. Isaías 14:3 promete alivio ''de tu dolor y tu tumulto'', el sufrimiento del exilio. La palabra puede abarcar dolor físico, angustia emocional y las dificultades de circunstancias adversas. Algunos intérpretes lo conectan con la palabra para ''ídolo'', sugiriendo que dolor e idolatría comparten una raíz, pero los contextos aquí claramente apoyan el significado de ''dolor''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6090b', 'spa', 'ídolo, imagen tallada', 'Este sustantivo designa un ídolo o imagen esculpida, distinto de los homónimos que significan ''dolor'' o ''vasija''. En Isaías 48:5 Dios declara que anunció eventos futuros de antemano para que Israel no pudiera atribuirlos a su ídolo. El término enfatiza la naturaleza fabricada y moldeada de los ídolos como objetos de manufactura humana. El contexto implica una polémica contra la idolatría y una afirmación de la soberanía única de Yahveh.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6091', 'spa', 'Ídolos, imágenes talladas: dioses falsos hechos de plata y oro, objetos de culto ilícito condenados reiteradamente en la literatura profética y sálmic', 'Ídolos, imágenes talladas: dioses falsos hechos de plata y oro, objetos de culto ilícito condenados reiteradamente en la literatura profética y sálmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6092', 'spa', 'obreros, trabajadores; los que laboran', 'Este sustantivo designa a obreros o trabajadores, con sufijo de segunda persona masculina plural: ''vuestros obreros''. En Isaías 58:3 aparece en la acusación de Dios de que Israel ayuna mientras oprime a sus trabajadores. El término deriva de raíces asociadas con el esfuerzo y la labor, enfatizando la naturaleza ardua del trabajo. El contexto enmarca una crítica de justicia social: la observancia religiosa no puede encubrir la explotación de quienes laboran.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6093', 'spa', 'Dolor, trabajo penoso; labor ardua y el sufrimiento asociado a ella', 'Este sustantivo aparece exclusivamente en los primeros capítulos de Génesis, denotando el dolor y el trabajo penoso introducidos por la Caída. Génesis 3:16 declara que la mujer dará a luz hijos ''con dolor'', intensificado el trabajo de parto por la maldición. Génesis 3:17 pronuncia que el hombre comerá ''con fatiga'' todos los días de su vida, volviéndose la agricultura laboriosa y frustrante. Génesis 5:29 explica el nombre de Noé como trayendo ''alivio de nuestro trabajo penoso y del dolor de nuestras manos'', el duro trabajo de cultivar la tierra maldita. La palabra abarca tanto el sufrimiento físico como el trabajo agotador, las dos dimensiones de la existencia humana bajo juicio. Sin embargo, el nombre de Noé ofrece esperanza de alivio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6094', 'spa', 'dolor, herida, tristeza — daño físico o emocional, sufrimiento o aflicción del corazón', 'Abarca tanto el dolor físico como la angustia emocional. En Job 9:28, el sufriente teme todos sus «dolores», mientras que el Salmo 147:3 celebra a Dios como quien «venda sus heridas». Proverbios lo emplea con matices distintos: el guiño del ojo causa «dolor» ajeno (10:10) y la tristeza del corazón abate el espíritu (15:13). El uso teológicamente más cargado aparece en el Salmo 16:4, donde «se multiplicarán sus dolores» describe a quienes persiguen dioses ajenos, presentando el sufrimiento como salario de la idolatría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6095', 'spa', 'cerrar, entrecerrar (especialmente los ojos)', 'Este verbo significa cerrar o entrecerrar, usado particularmente para referirse al acto de cerrar los ojos. En Proverbios 16:30 describe a quien cierra sus ojos para tramar perversidades, lo que sugiere un bloqueo deliberado de la verdad moral para concentrarse en la maldad. El participio indica acción habitual: alguien caracterizado por cerrar los ojos continuamente. La imagen evoca una ceguera moral voluntaria y calculada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6096', 'spa', 'espinazo, columna vertebral; hueso sacro cercano a la cola grasa del animal sacrificial', 'Este término anatómico designa el espinazo o, más específicamente, el sacro, es decir, el hueso cercano a la cola grasa de la oveja. Aparece en las instrucciones sacrificiales de Levítico relativas a la grasa que debía separarse y ofrecerse. El término con artículo, «el espinazo», indica un rasgo anatómico específico y reconocido. El contexto involucra la cola grasa propia de las ovejas del antiguo Cercano Oriente, siendo el hueso adyacente el punto de referencia para el corte sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6097', 'spa', 'árboles (colectivo); madera, leña', 'Este sustantivo femenino parece funcionar como colectivo para «árboles», aunque BDB señala incertidumbre textual. En Jeremías 6:6 aparece en la orden de talar árboles contra Jerusalén. La mayoría de los manuscritos y versiones sugieren leer la forma como un sufijo femenino de tercera persona sobre el sustantivo común para árbol o madera, dando «sus árboles» o «su madera». Tal como está, la forma sería un colectivo «árboles», pero la enmienda a una forma con sufijo es ampliamente aceptada por los especialistas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6098', 'spa', 'Consejo, advertencia, plan — orientación dada o recibida, ya sea deliberación humana, estrategia política o propósito soberano de Dios.', 'Consejo, advertencia, plan — orientación dada o recibida, ya sea deliberación humana, estrategia política o propósito soberano de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6099', 'spa', 'Poderoso, fuerte; numeroso, vasto — describiendo naciones, ejércitos o pueblos de gran fuerza o cantidad', 'Poderoso, fuerte; numeroso, vasto — describiendo naciones, ejércitos o pueblos de gran fuerza o cantidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6100', 'spa', 'Ezión-guéber, antigua ciudad portuaria en la cabecera del Golfo de Áqaba, cerca de Elat; estación del desierto y base naval.', 'Ezión-guéber fue una importante ciudad portuaria situada en el extremo norte del Golfo de Áqaba, cerca de la localidad de Elat. Sirvió primero como estación durante las peregrinaciones de Israel por el desierto (Núm 33:35-36; Deut 2:8) y más tarde como puerto de construcción naval y comercio de Salomón para las expediciones a Ofir (1 Re 9:26). La flota malograda de Josafat naufragó allí (1 Re 22:48). Las traducciones en distintos idiomas transliteran de forma consistente este nombre compuesto, con variaciones fonéticas según las convenciones de cada lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6101', 'spa', 'ser perezoso, indolente; actuar con pereza o desidia', 'Este verbo en Nifal significa ser perezoso, indolente, o mostrar desidia en la acción. En Jueces 18:9, los espías danitas instan a sus parientes a no ser perezosos para subir y poseer la tierra que han explorado. El verbo caracteriza la vacilación o la pereza que retrasa una acción oportuna. La forma reflexiva del Nifal sugiere hacerse negligente a uno mismo o permitirse la inactividad cuando la situación exige actuar con decisión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6102', 'spa', 'Perezoso, holgazán; quien evita el trabajo y padece escasez, figura arquetípica en la enseñanza sapiencial de Proverbios.', 'Adjetivo usado como sustantivo para designar a la persona habitualmente perezosa. El ʿatsel aparece exclusivamente en Proverbios como uno de los personajes tipo favoritos de los sabios. El sermón de la hormiga en Proverbios 6:6–9 se dirige al perezoso directamente: «Ve a la hormiga, oh perezoso; mira sus caminos y sé sabio», estableciendo un contraste entre la laboriosidad de la naturaleza y la indolencia humana que resuena a lo largo del libro. El camino del perezoso está cubierto de espinos (15:19), sus deseos quedan insatisfechos (13:4; 21:25–26) y resulta tan irritante como vinagre a los dientes y humo a los ojos para quien confía en él (10:26).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6104', 'spa', 'ociosidad, pereza; inactividad indolente', 'Este sustantivo femenino denota la ociosidad o pereza, la cualidad de ser inactivo o indolente. En Proverbios 31:27 describe aquello que la mujer virtuosa no consume: «el pan de la ociosidad». La expresión significa que ella no vive en la holganza improductiva, sino que se dedica activamente al trabajo fecundo. El término condena la inactividad estéril, especialmente cuando se consumen recursos sin aportar esfuerzo propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6105a', 'spa', 'Ser poderoso, fuerte o numeroso; en Piel, quebrantar huesos; en Hifil, fortalecer.', 'Ser poderoso, fuerte o numeroso; en Piel, quebrantar huesos; en Hifil, fortalecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6106', 'spa', 'Hueso, parte esquelética; en construcción con ''día'', ese mismo o aquel preciso; figuradamente, sustancia, cuerpo o esencia.', 'עֶצֶם es la palabra hebrea ordinaria para hueso —la estructura esquelética dura de personas y animales— pero desarrolla dos extensiones fascinantes que la hacen lexicográficamente rica. La primera es la construcción enfática בְּעֶצֶם הַיּוֹם הַזֶּה (''en el hueso de este día'', es decir, ''en ese mismo día''), donde el hueso-como-sustancia se convierte en marcador de identidad precisa y énfasis, apareciendo en momentos narrativos cruciales: el día en que comienza el Diluvio (Gn 7:13), el día de la circuncisión (Gn 17:23), el día del Éxodo (Éx 12:17). La segunda extensión alcanza la noción de ''sustancia'' o ''esencia'': el עֶצֶם del cielo en Éx 24:10 es su cuerpo mismo, diáfano como el zafiro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6107', 'spa', 'Ezem/Etzem; una ciudad en el Néguev asignada a Judá y luego a Simeón', 'Ezem fue una ciudad en el Néguev, la región meridional de la herencia de Judá. Josué 15:29 la enumera entre las ciudades sureñas de Judá, pero Josué 19:3 y 1 Crónicas 4:29 la asignan a Simeón, cuya herencia fue tallada desde el territorio de Judá. Las variantes textuales (Ezem/Etzem) reflejan diferentes vocalizaciones del mismo texto consonántico. El nombre puede relacionarse con la palabra para ''hueso'' o ''fuerza'', aunque la conexión es incierta. La ubicación de la ciudad en el árido Néguev sugiere que fue un pequeño asentamiento en la frontera sur, parte de la red defensiva contra incursiones nómadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6108', 'spa', 'Poder, huesos; fuerza y poder, o colectivamente el marco esquelético', 'Este sustantivo puede significar ''poder'' o ''huesos'' (colectivamente como estructura), mostrando rango semántico. Deuteronomio 8:17 advierte contra decir ''mi poder y el vigor de mi mano'' obtuvieron riqueza, atribuyendo el éxito a uno mismo en lugar de a Dios. Job 30:21 se queja de que Dios lo persigue ''con el vigor de Tu mano'', la fuerza divina vuelta contra el que sufre. Salmo 139:15 lo usa para significar ''estructura'' o marco esquelético: ''mi estructura no te fue oculta'' cuando era formado en el vientre. La palabra enfatiza fuerza vigorosa o la estructura sustancial que sostiene la fuerza. El vínculo semántico entre huesos y poder es natural: los huesos proveen el marco para el poder corporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6109', 'spa', 'Poder, fuerza; poder y fuerza abundantes', 'Este sustantivo femenino denota fuerza y poder poderoso, usado particularmente del poder abundante de Dios. Isaías 40:29 promete que Dios ''da esfuerzo al cansado y multiplica las fuerzas al que no tiene ningunas'', usando esta palabra para el vigor que Él suple. Isaías 47:9 advierte a Babilonia que calamidades vendrán sobre ella ''a pesar del gran poder de tus hechicerías'', su poder mágico resultando fútil. Nahúm 3:9 describe a Etiopía y Egipto como la fuerza de Nínive, preguntando ''¿acaso era infinito su poder?'' antes de detallar su caída. La palabra enfatiza fuerza robusta y vigorosa, el tipo de poder que parece abundante e inquebrantable hasta ser probado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6110', 'spa', 'argumento defensivo, prueba, evidencia presentada en contexto legal o retórico', 'Este sustantivo poco frecuente aparece únicamente en Isaías 41:21, donde Dios desafía a los ídolos a «presentar sus argumentos», es decir, sus pruebas más sólidas. El contexto es una escena de tribunal en la que los falsos dioses son sometidos a juicio. El término se traduce como «argumentos» o «pruebas», capturando la fuerza legal y retórica del pasaje. Deriva de una raíz que significa «ser fuerte», lo que sugiere que no se trata de excusas débiles, sino de la mejor evidencia que se pueda reunir en defensa de una posición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6111', 'spa', 'Azmón; un lugar en el extremo sur de la frontera de Canaán', 'Azmón fue un sitio en la frontera más meridional de la Tierra Prometida, marcando el límite entre Canaán y el desierto. Números 34:4-5 describe la frontera sur pasando por Azmón y procediendo hasta el arroyo de Egipto. Josué 15:4 lo incluye en la descripción de la frontera sur de Judá, usando lenguaje idéntico. La forma direccional Azmoná (''hacia Azmón'') aparece en Números 34:4. La ubicación precisa es incierta, en algún lugar del norte del Sinaí o el desierto del Néguev. Como marcador fronterizo, Azmón representaba la extensión del reclamo territorial de Israel, el borde donde la tierra prometida encontraba el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6113', 'spa', 'Restringir, encerrar, contener o confinar; también cerrar (cielos/vientre) o retener bajo el propio dominio', 'Restringir, encerrar, contener o confinar; también cerrar (cielos/vientre) o retener bajo el propio dominio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6114', 'spa', 'restricción, control; posiblemente riqueza (textualmente incierto en Jueces 18:7)', 'Esta palabra aparece en Jueces 18:7 en una frase notoriamente difícil que describe a los habitantes de Lais como quienes tenían un ''poseedor de restricción'', tal vez refiriéndose a un gobernante que ejerce control. Sin embargo, las versiones antiguas (griega y latina) lo entendieron como ''riqueza'', y el texto podría combinar dos términos hebreos distintos (tesoro y riqueza) que los escribas posteriores fusionaron. La variedad de traducciones refleja una genuina incertidumbre textual, y el significado original sigue siendo esquivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6115', 'spa', 'restricción, coerción, opresión; esterilidad del vientre', 'Este sustantivo poco común describe la restricción forzada o la opresión. En Isaías 53:8, aparece junto al juicio en la prueba del siervo sufriente, siendo llevado mediante coerción y proceso legal. Los Salmos lo usan para circunstancias angustiosas, mientras que Proverbios lo emplea metafóricamente para la ''restricción del vientre'' (esterilidad). La evidencia multilingüe se agrupa en torno a opresión y restricción, aunque las glosas en español y francés también capturan el matiz de esterilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6116', 'spa', 'Asamblea solemne, reunión sagrada — convocación formal que marca el cierre de un período festivo.', 'El sustantivo עֲצָרָה (atsará), de la raíz עצר (''retener, detener''), designa una asamblea solemne o reunión sagrada, típicamente la ceremonia de clausura de una festividad mayor. La Torá la prescribe para el octavo día de Sucot (Lv 23:36; Nm 29:35) y el séptimo día de Pascua/Panes sin Levadura (Dt 16:8). La celebración de Josafat (2 Cr 7:9) y la restauración de Nehemías (Neh 8:18) culminan ambas en tal asamblea. Sin embargo, proféticamente Dios puede rechazar las mismas asambleas que instituyó: Isaías declara «no puedo soportar iniquidad y asamblea solemne juntas» (Is 1:13), y Amós proclama que Dios aborrece las fiestas de Israel (Am 5:21). Joel convoca al pueblo a santificar un ayuno y proclamar asamblea solemne en arrepentimiento genuino (Jl 1:14; 2:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6117', 'spa', 'asir del talón, suplantar, engañar — agarrar el calcañar o aventajar con astucia', 'Verbo derivado de עָקֵב (talón), cuyo campo semántico se extiende desde el acto literal de agarrar el calcañar hasta la astucia y el engaño figurados. Su uso más célebre es el amargo juego de palabras de Esaú en Gn 27:36: «¿No se llama con razón Jacob? Pues me ha suplantado ya dos veces». Oseas 12:3 recuerda ese mismo gesto de asir el talón desde el vientre. En Jeremías 9:4, el verbo advierte que todo hermano «se hace un Jacob», es decir, engaña sin escrúpulo. Job 37:4 emplea un sentido afín de contener o retener, mostrando el alcance de la raíz desde la sujeción física hasta la traición moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6118', 'spa', 'Porque, a causa de (conjunción causal); fin, resultado; recompensa por la acción fiel.', 'ʿEqev es un sustantivo que significa «talón» o «consecuencia» y que evolucionó hacia una conjunción causal sin perder sus sentidos nominales de «fin» y «recompensa». En su uso predominante funciona como «porque»: Dios bendice a Abraham «por cuanto obedeciste mi voz» (Gn 22:18; 26:5). El vínculo etimológico con «talón» ilumina la lógica: las consecuencias siguen a las acciones como el talón sigue al pie. En los Salmos, ʿeqev significa «hasta el fin» (Sal 119:33, 112), y en la literatura sapiencial designa la «recompensa» que corona la vida obediente (Sal 19:11; Prov 22:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6119', 'spa', 'El talón del pie; por extensión una huella, rastro o casco; figuradamente la retaguardia de un ejército', 'Comenzando por el talón literal — la parte del cuerpo que Jacob famosamente agarró al nacer (Gn 25:26) — esta palabra se extiende naturalmente hacia las marcas que un talón deja: huellas y rastros. El salmista se maravilla de que las pisadas de Dios (ʿiqqĕvôt) por el mar no dejaron rastro (Sal 77:19), mientras que a la amada en el Cantar de los Cantares se le dice que siga las huellas del rebaño (1:8). El sentido anatómico se expresa con ''talón'' o ''calcáñar'', mientras que ''huellas'' y ''pisadas'' capturan el significado metafórico. Un uso militar en Josué 8:13 designa la retaguardia de la fuerza de emboscada de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6120', 'spa', 'los que se aprovechan insidiosamente, suplantadores, engañadores que hacen tropezar a otro', 'En el Salmo 49:5 el salmista lamenta: ''la iniquidad de mis suplantadores me rodea'', refiriéndose a quienes maquinan para obtener ventaja injusta y hacer tropezar al prójimo mediante la astucia. La raíz evoca la imagen del talón (עָקֵב), recordando cómo Jacob agarró el talón de Esaú al nacer y luego lo suplantó. El español lo traduce como ''mis talones'', quizá leyendo la frase como enemigos que persiguen de cerca, pisándole los talones. En todo caso, la palabra transmite un engaño traicionero dirigido a obtener ventaja sobre otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6121b', 'spa', 'escarpado, montañoso, terreno abrupto (en contraste con terreno llano)', 'Isaías 40:4 describe una gran nivelación del paisaje en preparación para la venida de Dios: ''Lo escarpado se convertirá en llanura''. Este adjetivo describe un terreno accidentado y montañoso, difícil de recorrer, en contraste con las planicies. La raíz tiene cognados en árabe y etiópico que significan ''sendero de montaña difícil'' y ''colina''. El español lo traduce como ''lo torcido'', quizá viendo una metáfora moral junto al sentido geográfico. El versículo trata de remover obstáculos, ya sean montañas literales o barreras figuradas, para que la gloria de Dios sea revelada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6122', 'spa', 'astucia, artimaña, engaño insidioso usado para embaucar', 'En 2 Reyes 10:19, Jehú actúa ''con astucia'', empleando el engaño para atraer a los adoradores de Baal a una trampa y poder aniquilarlos. La palabra transmite insidiosidad: un enfoque solapado y artero para lograr un objetivo. Aunque el propósito de Jehú —destruir el culto a Baal— se presenta como sancionado por Dios, el método implica un engaño deliberado: fingir honrar a Baal para reunir a todos sus adoradores en un solo lugar y ejecutarlos. El término capta el uso moralmente ambiguo de la artimaña para un fin supuestamente justo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6123', 'spa', 'atar, sujetar firmemente (especialmente atar los miembros entre sí)', 'Este verbo aparece únicamente en Génesis 22:9, la estremecedora escena en que Abraham ''ató a Isaac'' sobre el altar, preparándose para sacrificarlo. Las lenguas cognadas (hebreo, arameo, árabe, siríaco, etiópico) comparten significados relacionados con atar, sujetar o plegar los miembros. El Targum arameo usa la misma raíz tanto para atar como para arrodillar, reflejando quizá la postura de una víctima atada. La escena es una de las más emocionalmente intensas de las Escrituras: un padre atando a su hijo amado en obediencia al mandato de Dios, momentos antes de que el ángel intervenga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6124', 'spa', 'Rayado, listado; describe las marcas en las ovejas y cabras de Jacob en el relato de la cria de ganado', 'Este adjetivo describe animales con rayas o franjas visibles en su pelaje, y aparece exclusivamente en el relato de Jacob y Laban sobre la cria de ganado en Genesis 30-31. Se refiere a las ovejas y cabras con marcas distintivas que constituyeron el salario de Jacob mediante su estrategia de cria guiada por Dios. El termino siempre se emplea junto con palabras afines para animales moteados y pintados, formando un campo lexico especifico para las marcas del ganado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6125', 'spa', 'presión, opresión, o posiblemente clamor de auxilio (textualmente debatido en el Salmo 55:3)', 'El Salmo 55:3 emplea esta rara palabra de origen arameo, traducida como «por la opresión de los impíos». El salmista se encuentra angustiado, y este término capta el peso aplastante de las fuerzas hostiles. Sin embargo, algunos eruditos proponen que el texto debería leerse como «clamor» (צְעָקַת), lo cual haría un paralelismo con «voz» (קוֹל) mencionado antes en el versículo y encajaría mejor en el contexto de un clamor dirigido a Dios. Ya sea «presión» o «clamor», el sentido apunta a una tribulación abrumadora causada por los enemigos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6126', 'spa', 'Acub — nombre propio de varios personajes postexilicos: un descendiente davidico, porteros levitas y jefes de familias', 'Acub es un nombre personal hebreo que aparece en diversos contextos postexilicos. Identifica a un descendiente de David en la genealogia real (1 Cr 3:24), varios porteros levitas apostados en el Templo (1 Cr 9:17; Neh 11:19; 12:25), jefes de familias que regresaron de Babilonia (Esd 2:42 = Neh 7:45) y un levita que ayudo a Esdras a explicar la Tora al pueblo (Neh 8:7). El nombre probablemente deriva de una raiz que significa ''vigilar'' o ''guardar'', lo cual concuerda con la funcion de portero que desempenaron varios de sus portadores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6127', 'spa', 'torcido, retorcido, pervertido (participio pasivo que describe distorsión)', 'Habacuc 1:4 lamenta que «la justicia sale pervertida», es decir, torcida y deformada como un metal o una madera forzados hasta quedar deformes. Este participio pasivo evoca algo originalmente recto que ha sido distorsionado. La raíz verbal significa torcer o doblar y aparece en hebreo, arameo, siríaco y árabe con sentidos similares. El profeta denuncia un sistema legal tan corrupto que lo que debería ser recto —la justicia— emerge torcido. La imagen es la de algo que ha sido doblado a la fuerza hasta perder su forma original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6129', 'spa', 'sinuoso, tortuoso (adjetivo); posiblemente la constelación Draco (el dragón/serpiente)', 'Isaías 27:1 habla de «Leviatán, la serpiente tortuosa», utilizando este adjetivo para describir la forma sinuosa y enroscada del monstruo marino mítico. Algunos eruditos sugieren que también podría referirse a la constelación Draco, el dragón celestial que se enrosca en torno al cielo septentrional. La palabra transmite la idea de algo que se mueve en curvas, no en línea recta: un camino serpentino y evasivo. En la imaginería apocalíptica, Leviatán representa el caos y el mal que Dios destruirá finalmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6130', 'spa', 'Acán, nombre propio edomita (Génesis 36:27); variante Jaacán en Crónicas', 'Acán es un nombre que aparece en la genealogía de Edom en Génesis 36:27, donde figura entre los hijos de Ezer. El pasaje paralelo en 1 Crónicas 1:42 presenta el nombre como Jaacán, y otras referencias hablan de «los hijos de Jaacán» y «los pozos de los hijos de Jaacán», lo que sugiere que sus descendientes llegaron a formar un clan o asentamiento reconocido. La variación textual entre Acán y Jaacán es menor y probablemente refleja diferentes pronunciaciones o tradiciones de copistas. El nombre es edomita, perteneciente a las genealogías que trazan a los descendientes de Esaú.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6131b', 'spa', 'desjarretar — cortar los tendones de las patas de caballos o bueyes para inutilizarlos', 'Verbo denominativo en Piel derivado de una raíz que significa «tendón» o «nervio», usado exclusivamente para designar el acto de desjarretar animales, es decir, cortar los tendones de las patas de caballos o bueyes para dejarlos inservibles. En contextos bélicos (Jos 11:6, 9; 2 S 8:4), Dios ordena o David ejecuta esta acción sobre caballos de carros capturados, asegurando que Israel no dependa de la caballería militar. En Gn 49:6, la reprensión de Jacob a Simeón y Leví recuerda su violencia gratuita: «desjarretaron un buey». El español «desjarretar» refleja con precisión este acto específico de inutilizar mediante el corte de los tendones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6133', 'spa', 'vástago, rama, miembro de una familia o clan que procede de una raíz', 'Levítico 25:47 emplea este término en un contexto legal: si un israelita empobrece y se vende a un extranjero residente, puede ser redimido por «un vástago de la familia del extranjero», es decir, una rama o miembro que brota del árbol familiar. La palabra evoca una imagen botánica, como un brote que crece desde la raíz de una planta, y enfatiza la conexión de parentesco, incluso cuando es extendida o indirecta. Esta disposición legal permite que hasta un pariente lejano del amo extranjero pueda actuar como redentor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6134', 'spa', 'Équer, nombre propio de un varón de la tribu de Judá (1 Crónicas 2:27)', 'Équer es un nombre que aparece en la genealogía de Judá en 1 Crónicas 2:27, donde se le menciona entre los hijos de Jerameel, perteneciente a los clanes judaítas. Este nombre solo aparece una vez en las Escrituras, y las versiones griegas antiguas lo transliteran de diversas formas (Akor, Ikar). Más allá de esta única referencia, no se sabe nada adicional sobre Équer: es uno de tantos nombres que preservan la memoria de las familias israelitas tempranas. Las genealogías de Crónicas buscaban anclar al Israel postexílico en su herencia tribal, recordando incluso a figuras oscuras como Équer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6135', 'spa', 'Estéril, infértil — incapaz de engendrar hijos; dicho de mujeres, y una vez de varones y ganado; revertido por Dios', 'El adjetivo עָקָר (aqar) describe la incapacidad de procrear. Marca a las mujeres de mayor peso teológico en Génesis: Sara (Gn 11:30), Rebeca (Gn 25:21) y Raquel (Gn 29:31). El motivo de la esterilidad matriarcal subraya que los hijos de la alianza llegan como don divino, no como resultado natural. Jueces 13:2-3 lo aplica a la esposa de Manoa antes del nacimiento de Sansón, y el Salmo 113:9 celebra que Dios hace habitar a la estéril como madre gozosa. Deuteronomio 7:14 extiende la promesa tanto a hombres como a mujeres, e incluso al ganado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6136', 'spa', 'raíz, tronco, tocón (de un árbol)', 'Este sustantivo arameo aparece exclusivamente en la visión de Daniel del gran árbol, donde a Nabucodonosor se le ordena dejar el ''tocón de sus raíces'' en el suelo después de que el árbol sea cortado. La imagen transmite tanto juicio (el corte) como esperanza (el tocón permanece viable para futuro rebrote). La frase ''tocón de sus raíces'' combina dos términos relacionados con raíz para dar énfasis, indicando que aunque el reino es quitado, el fundamento permanece para eventual restauración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6137', 'spa', 'Escorpión: el arácnido venenoso, usado literalmente de la fauna del desierto y figuradamente de instrumentos de castigo severo.', 'Designa al escorpión, criatura bien conocida en los desiertos de Judea y del Sinaí por su dolorosa picadura venenosa. Moisés recuerda cómo Dios condujo a Israel por un desierto de serpientes y escorpiones (Deut 8:15), mientras que a Ezequiel se le dice que no tema a Israel rebelde aunque more entre escorpiones (Ezeq 2:6). El uso más vívido es figurado: Roboam amenaza con disciplinar al pueblo con «escorpiones» en vez de azotes (1 Rey 12:11, 14 = 2 Cró 10:11, 14), denotando casi con certeza látigos con púas metálicas cuyo golpe evocaba la picadura del animal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6138', 'spa', 'Ecrón — la más septentrional de las cinco ciudades principales filisteas, sede del dios Baal-zebub', 'Ecrón — la más septentrional de las cinco ciudades principales filisteas, sede del dios Baal-zebub');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6140', 'spa', 'torcer, hacer torcido, pervertir — distorsionar lo recto o lo justo', 'Enraizado en la idea de torcer físicamente, este verbo se extiende con fuerza al terreno moral y judicial. En su forma Piel describe la distorsión deliberada de caminos, justicia o conducta: los líderes de Miqueas 3:9 «tuercen todo lo recto» y en Isaías 59:8 los malvados «han torcido sus sendas». El participio Nifal en Proverbios 28:18 describe a quien es «perverso en sus caminos», mientras que el Hifil en Job 9:20 presenta a Dios declarando perversa a una persona. La imagen central es la de doblar aquello que debería permanecer recto, tanto en sentido físico como moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6141', 'spa', 'Torcido, perverso — moralmente desviado o engañoso en palabra, conducta o carácter', 'El adjetivo עִקֵּשׁ (iqqesh) describe la torcedura moral, la perversidad o la distorsión: lo opuesto al camino recto e íntegro. Proverbios es el libro que más lo emplea, contraponiendo al «torcido» con el recto (יָשָׁר): «los perversos de corazón son abominación a Jehová» (Pr 11:20), y «mejor es el pobre que camina en integridad que el torcido en sus caminos» (Pr 19:1; 28:6). Deuteronomio 32:5 llama a Israel rebelde «generación torcida y perversa». En 2 Samuel 22:27 (= Sal 18:27), Dios se muestra sagaz con el torcido. Proverbios 8:8 insiste en que las palabras de la sabiduría no contienen nada torcido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6142', 'spa', 'Iques, un guerrero de Tecoa, padre de Ira', 'Iques fue un hombre de Tecoa, padre de Ira, uno de los valientes guerreros de David. Aparece en el registro de los treinta combatientes de élite de David y posteriormente en la organización administrativa bajo David y Salomón. El nombre aparece consistentemente en Samuel y Crónicas, identificando el distinguido servicio militar de esta familia tecoíta. Crónicas añade que Ira hijo de Iques sirvió como oficial sobre su división durante el sexto mes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6144', 'spa', 'Ar: ciudad o distrito moabita al sur del Arnón, prominente en el itinerario de Israel por el desierto.', 'Topónimo que designa la ciudad capital o un distrito más amplio de Moab situado al sur del desfiladero del Arnón. El nombre posiblemente deriva de la raíz semítica común para «ciudad» (cognado del hebreo עִיר), y las inscripciones sudarabígonas atestiguan עָר como altura fortificada. Aparece en el fragmento poético que celebra la aproximación de Israel al Arnón (Núm 21:15) y se denomina «Ar de Moab» en el oráculo contra Moab (Núm 21:28; Isa 15:1). Dios instruye a Israel a no hostigar a Moab porque Ar ha sido dado a los descendientes de Lot (Deut 2:9, 18, 29). Las traducciones transliteran consistentemente el nombre como un topónimo irreducible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6147', 'spa', 'Er, nombre propio: principalmente el primogénito de Judá, muerto por Dios a causa de su maldad', 'Nombre propio que significa «vigilante» o «despierto», relacionado con la raíz que denota estar alerta. Er es conocido sobre todo como el primogénito de Judá, cuya maldad ante los ojos de Dios provocó su muerte antes de que pudiera dejar descendencia (Gn 38:7), lo que desencadena el dramático relato de Tamar. El nombre reaparece en las genealogías de 1 Crónicas, donde un Er posterior figura como descendiente de Judá por la línea de Sela (1 Cr 4:21). Todas las traducciones principales simplemente transliteran el nombre como «Er».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6148', 'spa', 'Salir fiador o dar una prenda; también mezclarse o asociarse; por extensión, intercambiar o comerciar; raramente, ser agradable', 'Salir fiador o dar una prenda; también mezclarse o asociarse; por extensión, intercambiar o comerciar; raramente, ser agradable');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6149', 'spa', 'Ser dulce, agradable o grato; del sueno, la meditacion, los deseos y las ofrendas sacrificiales que agradan a alguien', 'Este verbo estativo expresa la cualidad de ser dulce, agradable o placentero para alguien. Abarca dominios tanto sensoriales como espirituales: el sueno que es dulce (Pr 3:24; Jer 31:26), la meditacion que agrada a Dios (Sal 104:34) y las ofrendas sacrificiales que agradan o dejan de agradar al Senor (Jer 6:20; Mal 3:4; Os 9:4). Los usos negativos son especialmente impactantes: los profetas declaran que las ofrendas de Israel no son gratas a Dios a causa de su infidelidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6150', 'spa', 'oscurecerse, hacerse de tarde; atardecer', 'Este verbo denominativo de ''tarde'' (עֶרֶב) describe el inicio de la oscuridad cuando el día transita hacia la noche. En Jueces 19:9, se refiere al día declinando hacia la tarde. 1 Samuel 17:16 usa el infinitivo para describir las apariciones dos veces al día de Goliat, ''por la mañana y por la tarde''. Isaías 24:11 lo emplea figuradamente—todo gozo ''se ha oscurecido''—aunque algunos eruditos sugieren enmendar el texto. El verbo captura tanto el crepúsculo literal como el oscurecimiento metafórico de luz o gozo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6151', 'spa', 'mezclado, mixto; combinado o entremezclado, usado de metales o pueblos en la visión de Daniel', 'Verbo arameo que significa mezclar o entremezclar, presente únicamente en Daniel 2 dentro de la visión de la estatua con materiales mixtos. El participio pasivo describe el hierro ''mezclado con'' barro cocido (2:41), representando un reino de fuerza mixta. Las formas reflexivas (2:43, apareciendo dos veces) describen cómo ''se mezclarán'' mediante matrimonios mixtos, pero sin lograr unirse, tal como el hierro no se amalgama verdaderamente con el barro. Esta imagen retrata un reino dividido: pueblos diversos unidos políticamente pero sin genuina cohesión. La metáfora de la mezcla capta tanto el intento de integración como la incompatibilidad inherente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6152b', 'spa', 'Arabia; las regiones desérticas del norte de Arabia y sus habitantes, nómadas y comerciantes del desierto', 'Término colectivo para los moradores de la estepa del norte de Arabia, extendido posteriormente a toda la península. Las referencias bíblicas se centran en las tribus nómadas del desierto septentrional: Jeremías menciona a los «reyes de Arabia que habitan en el desierto» (25:24), mientras que Reyes y Crónicas registran el tributo de Arabia a Salomón (1 R 10:15; 2 Cr 9:14). Ezequiel incluye a Arabia entre los socios comerciales (27:21) y las naciones sujetas a juicio (30:5). El nombre deriva de la raíz que significa «desierto» o «estepa», reflejando el modo de vida nómada que caracterizaba a estos pueblos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6153', 'spa', 'Tarde, período desde la media tarde hasta la puesta del sol; en forma dual, el ritual ''entre las dos tardes'' o intervalo crepuscular.', 'עֶרֶב marca el límite diario entre luz y oscuridad que estructura el tiempo bíblico. Dado que el día israelita comenzaba al ponerse el sol, עֶרֶב portaba un peso teológico que va mucho más allá de una simple indicación horaria: era el umbral de un nuevo día (Gn 1:5), el momento de purificación de la impureza (Lv 11:24-25) y la hora del sacrificio vespertino. La forma dual הָעַרְבַּיִם, ''las dos tardes'', aparece casi exclusivamente en legislación sacerdotal para fijar la ventana crepuscular precisa del sacrificio del cordero pascual (Éx 12:6) y la ofrenda diaria del tamid (Éx 29:39). El debate rabínico sobre si designa ''de la puesta del sol a la oscuridad'' o ''del sol declinante a la puesta'' refleja la antigua precisión del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6154a', 'spa', 'Multitud mixta: grupo heterogéneo de no israelitas agregados a Israel o a otra nación.', 'Designa una compañía mixta de extranjeros que se adhieren a un pueblo mayor, sobre todo la multitud diversa que partió de Egipto junto con Israel (Éxod 12:38). En las reformas de Nehemías, la «mezcla de gentes» es separada de Israel para restaurar la pureza étnica y pactual (Neh 13:3). Jeremías aplica el término a poblaciones extranjeras mezcladas entre los aliados de Egipto (Jer 25:20, 24) y entre los caldeos (Jer 50:37), donde su deslealtad bajo asedio se convierte en una vulnerabilidad militar. La palabra conlleva una connotación consistentemente peyorativa o al menos marginal: se trata de personas cuya lealtad e identidad permanecen ambiguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6154b', 'spa', 'Trama, los hilos horizontales entretejidos con la urdimbre en el telar, usada exclusivamente en las leyes levíticas sobre contaminación textil.', 'Término técnico de tejeduría (עֵרֶב) que designa la trama, es decir, los hilos transversales que se pasan a través de los hilos verticales de la urdimbre en un telar. Las nueve apariciones se concentran en Levítico 13:48-59, la legislación sacerdotal detallada que regula la contaminación en tejidos. La trama siempre se menciona junto a su contraparte, la urdimbre (שְׁתִי), mientras el sacerdote examina vestiduras en busca de señales de enfermedad propagada. La raíz hebrea עָרַב (''mezclar, entrelazar'') describe con precisión cómo los hilos de la trama se entrelazan con los de la urdimbre para formar la tela.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6155', 'spa', 'sauce o alamo (populus Euphratica), arbol ripareno que crece junto a arroyos y cursos de agua', 'Sustantivo que designa al sauce o alamo del Eufrates (populus Euphratica), un arbol que prospera a la orilla de corrientes de agua. En Lv 23:40, se recogen ramas de sauces del arroyo para la Fiesta de los Tabernaculos. El celebre Sal 137:2 retrata a los exiliados colgando sus arpas en los sauces junto a los rios de Babilonia. En Is 44:4, los justos brotan ''como sauces junto a corrientes de agua.'' Job 40:22 situa este arbol en el habitat del Behemot, subrayando su asociacion constante con ambientes humedos y riberas fluviales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6157', 'spa', 'Enjambre de insectos, tradicionalmente moscas o mezcla de criaturas nocivas, enviado como la cuarta plaga sobre Egipto.', 'Designa el enjambre (עָרֹב) enviado como la cuarta plaga egipcia, probablemente derivado de la raíz עָרַב que significa ''mezclar'', lo cual sugiere un enjambre mixto de insectos nocivos más que una sola especie. La Septuaginta lo traduce como κυνόμυια (''mosca canina''), mientras que la tradición rabínica lo entendió como una mezcla de fieras o diversas criaturas ponzoñosas. Las nueve apariciones se concentran en Éxodo 8 y dos salmos que rememoran la narrativa de las plagas (Sal 78:45; 105:31). En español se emplean tanto ''enjambre'' como ''mezcla'', reflejando la antigua ambigüedad sobre si el término enfatiza la acción colectiva del enjambre o la composición mixta de la plaga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6158', 'spa', 'Cuervo; ave impura de plumaje negro, alimentada por Dios como señal de su providencia', 'Designa al cuervo común (Corvus corax), ave grande, inteligente y de plumaje negro azabache que protagoniza varias escenas bíblicas memorables. Noé envió primero un cuervo desde el arca (Gn 8:7), los cuervos alimentaron a Elías junto al arroyo de Querit (1 R 17:4, 6), y Dios mismo provee alimento a los cuervos jóvenes (Job 38:41; Sal 147:9). Figura entre las aves impuras (Lv 11:15; Dt 14:14) y aparece también como símbolo de belleza: los cabellos del amado son «negros como el cuervo» (Cnt 5:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6159', 'spa', 'Oreb, principe madianita ejecutado por Efrain junto a la pena que lleva su nombre durante la campana de Gedeon', 'Oreb es el nombre de uno de los dos principes madianitas (el otro es Zeeb) capturados y ejecutados por los efraimitas durante la persecucion tras la dramatica victoria nocturna de Gedeon sobre el campamento de Madian. Fue muerto junto a una pena que desde entonces llevo su nombre, ''la pena de Oreb'' (Jue 7:25). Este acontecimiento se convirtio en paradigma de la liberacion decisiva de Dios: Isaias lo evoca como ''la matanza de Madian en la pena de Oreb'' (Is 10:26), y el salmista lo invoca como oracion pidiendo una victoria similar (Sal 83:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6160', 'spa', 'La Arabá (nombre propio del valle del Rift); llanuras o estepas adyacentes a un lugar; desierto o páramo árido.', 'La Arabá (nombre propio del valle del Rift); llanuras o estepas adyacentes a un lugar; desierto o páramo árido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6162', 'spa', 'prenda, depósito de garantía dado como seguridad', 'Este término describe una prenda o depósito de garantía dado para asegurar una promesa. Aparece exclusivamente en Génesis 38, donde Judá promete a Tamar un cabrito pero carece de él en el momento. Ella solicita su sello, cordón y bastón como colateral—un ''erabón'' hasta que él envíe el pago. La palabra entró al griego como ''arrabón'', usado en el Nuevo Testamento para el Espíritu Santo como garantía de herencia futura (2 Corintios 1:22; 5:5; Efesios 1:14). La narrativa muestra tanto el dar como el recibir de vuelta la prenda una vez cumplida la obligación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6163b', 'spa', 'Árabe, arabio — adjetivo gentilicio que designa a una persona o pueblo procedente de Arabia.', 'El gentilicio עֲרָבִי identifica a un individuo o grupo como árabe, empleándose tanto en singular para un personaje concreto como en plural para referirse colectivamente a los pueblos árabes. El adversario de Nehemías, Gesem, es llamado ''el árabe'' (Neh 2:19; 6:1), señalándolo como un líder influyente de la confederación tribal árabe que se opuso a la reconstrucción de Jerusalén. El plural ''los árabes'' aparece en Crónicas para designar a grupos árabes que trajeron tributo a Josafat (2 Cr 17:11) y que luego asaltaron Judá durante el reinado de Joram (2 Cr 21:16; 22:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6165', 'spa', 'anhelar, jadear (como un ciervo sediento)', 'Este verbo evocador captura un anhelo intenso o una sed intensa, como un ciervo jadeando por agua. El Salmo 42 lo usa dos veces en su famosa apertura: ''Como el ciervo brama por las corrientes de las aguas, así clama por ti, oh Dios, el alma mía.'' La imagen de un animal buscando agua desesperadamente se convierte en la metáfora de la sed espiritual. Joel 1:20 extiende esto a las bestias salvajes que claman por agua durante la sequía. El verbo transmite no un mero deseo sino un anhelo urgente y físico—una añoranza que consume todo el ser.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6166a', 'spa', 'Arad; ciudad cananea en el Néguev, lugar del conflicto de Israel con su rey', 'Ciudad cananea situada en la región meridional del Néguev, probablemente la actual Tell Arad, a unos 26 kilómetros al sur de Hebrón. Números 21:1 y 33:40 relatan cómo el «rey de Arad» atacó a Israel y la posterior destrucción de las ciudades cananeas. La lista de conquistas de Josué incluye al rey de Arad entre los gobernantes derrotados (12:14), y Jueces 1:16 menciona Arad en relación con el asentamiento de los ceneos. Los registros egipcios hacen referencia a «a-ru-da», confirmando la importancia antigua de este enclave. Su identidad como fortaleza clave del Néguev es consistente en todos los textos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6166b', 'spa', 'Arad, nombre propio de un varón de la tribu de Benjamín (1 Crónicas 8:15)', 'Este Arad es un benjaminita mencionado en 1 Crónicas 8:15, distinto de la más conocida ciudad cananea de Arad en el Néguev. Aparece en la genealogía de Benjamín como uno de los numerosos descendientes trazados a través de los clanes de esa tribu. Las versiones griegas transliteran el nombre de diversas formas (Orēr, Arōd, Arad), reflejando distintas tradiciones manuscritas. El texto no ofrece explicación alguna del nombre, y este Arad individual es por lo demás desconocido. Es uno de los muchos benjaminitas cuyos nombres se conservan en el esfuerzo del Cronista por documentar la estructura tribal de Israel tras el exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6167', 'spa', 'Asnos salvajes, burros indómitos (forma aramea usada en Daniel)', 'Daniel 5:21 relata cómo Nabucodonosor fue expulsado de la sociedad humana y «su morada fue con los asnos salvajes». Esta palabra aramea para asno salvaje subraya la degradación del rey, reducido a vivir como un animal, pastando entre las bestias indómitas del campo. El asno salvaje es símbolo de libertad y fiereza en la literatura bíblica, pero aquí resalta la humillación de un monarca otrora poderoso. El término es cognado con voces hebreas, siríacas y arameas para el mismo animal. El contexto enfatiza la pérdida total de dignidad y razón humanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6168', 'spa', 'Desnudar, descubrir, despojar; también derramar o vaciar un recipiente; reflexivamente desnudarse o extenderse', 'En su esencia, este verbo significa quitar lo que cubre, ya sea ropa, muros o el contenido de un recipiente. Rebeca ''vació'' su cántaro en el abrevadero (Gn 24:20), el salmista clama ''¡arrasad!'' contra la destrucción de Jerusalén por parte de Edom (Sal 137:7), e Isaías advierte que Dios ''descubrirá'' las frentes de las hijas de Sión (Is 3:17). El sentido de derramar puede parecer distante del de desnudar, pero ambos comparten la idea de exponer o liberar lo que estaba contenido. ''Arrasar'' capta el sentido de despojar, mientras que ''derramar'' y ''vaciar'' muestran cómo el significado se ramifica desde una misma imagen raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6169', 'spa', 'Lugares desnudos, posiblemente vegetación despojada junto al Nilo o riberas expuestas', 'Isaías 19:7 menciona «lugares desnudos» junto al Nilo, refiriéndose posiblemente a zonas de suelo expuesto donde la vegetación ha sido arrancada, o quizás a juncos y hierbas cosechados que dejan las riberas al descubierto. El hebreo es incierto: la versión griega lo traduce como «juncos» (ἄχει), y algunos estudiosos creen que la palabra original se refería a plantas, no a terreno vacío. El contexto es una profecía sobre la desolación de Egipto, donde las otrora fértiles riberas del Nilo dejarán de producir. Sea suelo desnudo o plantas marchitas, la imagen transmite pérdida y esterilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6170', 'spa', 'era de jardín, terraza; parcela cultivada o lecho elevado en un huerto, especialmente para plantas aromáticas', 'Término que designa eras o terrazas de jardín: parcelas elevadas y cultivadas donde las plantas crecen en hileras ordenadas. En el Cantar de los Cantares aparece en imágenes poéticas: «eras de bálsamo» (5:13), donde las mejillas del amado se comparan con terrazas fragantes, y «eras de especias» (6:2), donde el amado apacienta su rebaño y recoge lirios. Ezequiel lo emplea metafóricamente para la parcela donde se planta una vid (17:7, 10), representando el territorio de Jerusalén. El término sugiere cultivo intencional y orden, distinguiéndose del crecimiento silvestre: jardines con diseño deliberado y plantas aromáticas o valiosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6171', 'spa', 'Onagro, asno salvaje indómito (probable préstamo arameo, equivalente al hebreo פֶּרֶא)', 'Job 39:5 pregunta: «¿Quién dejó libre al asno salvaje?», usando este término que es probablemente un préstamo arameo equivalente al más común hebreo פֶּרֶא. El onagro es una criatura del desierto abierto, libre e indómita, que simboliza la independencia y la fiereza de una creación que nada debe al dominio humano. El discurso de Dios en Job 38-41 destaca animales que viven fuera del control del hombre, y el asno salvaje es el ejemplo por excelencia: nadie lo ha domesticado, nadie lo alimenta, y sin embargo prospera en el yermo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6172', 'spa', 'Desnudez, exposición del cuerpo; por extensión vergüenza, indecencia o vulnerabilidad sexual.', 'Desnudez, exposición del cuerpo; por extensión vergüenza, indecencia o vulnerabilidad sexual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6173', 'spa', 'deshonra, vergüenza, exposición (cognado arameo del hebreo עֶרְוָה)', 'Esdras 4:14 emplea esta palabra aramea cuando los adversarios de los judíos escriben al rey persa: «no nos conviene ver la deshonra del rey». El término es cognado del hebreo עֶרְוָה (desnudez, vergüenza) y transmite la idea de exposición y desgracia. El contexto es político: los autores de la carta afirman lealtad al rey y declaran que no pueden tolerar que sea deshonrado, presentando la reconstrucción de Jerusalén como una amenaza. La palabra evoca vulnerabilidad y pérdida de dignidad ante la mirada pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6174', 'spa', 'Desnudo, sin vestiduras: sin ropas, ya sea literalmente despojado o figuradamente desamparado y expuesto.', 'Desnudo, sin vestiduras: sin ropas, ya sea literalmente despojado o figuradamente desamparado y expuesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6175', 'spa', 'Astuto o sagaz — en sentido positivo: prudente, sensato (Proverbios); en sentido negativo: taimado, artero (Gn 3:1; Job)', 'Este adjetivo se mueve en el filo entre la sabiduría y el engaño. En Proverbios es enteramente positivo: la persona עָרוּם prevé el peligro y se resguarda (22:3; 27:12), actúa con conocimiento (13:16) y se contrapone al necio (פְּתִי) y al simple. Sin embargo, en Génesis 3:1 la serpiente es descrita como עָרוּם más que cualquier animal del campo: astuta al servicio del engaño. Job 5:12 y 15:5 también lo emplean negativamente, hablando de «las maquinaciones de los astutos» y «la lengua de los taimados». Una misma raíz abarca así todo el espectro de la inteligencia aguda, desde el discernimiento encomiable hasta la astucia manipuladora; solo el contexto determina qué polo está en juego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6177', 'spa', 'Aroer: ciudad fortificada al borde del desfiladero del Arnón, que marca el límite sur de Israel en Transjordania.', 'Aroer: ciudad fortificada al borde del desfiladero del Arnón, que marca el límite sur de Israel en Transjordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6178', 'spa', 'espantoso, terrible (adjetivo que describe un barranco o desfiladero aterrador)', 'Job 30:6 describe a los indigentes como habitantes «de los barrancos más espantosos», usando este adjetivo para transmitir terror y desolación. La palabra probablemente es un participio pasivo que significa «temido» o «atroz», aplicado a un paisaje tan inhóspito y aterrador que solo los desesperados buscan refugio allí. El término evoca no solo peligro físico sino la cualidad lúgubre y espeluznante de cañones desolados donde se esconden los marginados. Job relata la degradación de quienes antes lo despreciaban: personas reducidas a habitar lugares terroríficos e inhabitables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6180', 'spa', 'el erita, gentilicio colectivo que designa al clan descendiente de Eri (Números 26:16)', 'Números 26:16 menciona a «los eritas» como uno de los clanes de Gad, descendientes de Eri. El término es un gentilicio (adjetivo étnico o de clan) usado colectivamente con el artículo para designar a todo el grupo familiar. En el censo del desierto, cada tribu se subdivide en clanes, y este es una de las subdivisiones dentro de Gad. El nombre Eri es oscuro y solo se conoce en este contexto genealógico. Los eritas forman parte de la estructura tribal que organiza la vida militar y social de Israel durante el período del desierto y la conquista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6181', 'spa', 'Desnudez, desamparo — estado de estar sin vestiduras, usado literal y figuradamente para expresar exposición y vulnerabilidad.', 'Designa la condición de estar desnudo o expuesto, con connotaciones de vergüenza, indigencia y vulnerabilidad. La extensa alegoría de Ezequiel sobre Jerusalén como una niña abandonada y luego esposa infiel emplea abundantemente este término: la niña expósita estaba ''desnuda y descubierta'' (Ez 16:7), estado del cual Dios la rescató, pero al que amenaza con devolverla como castigo por su infidelidad (Ez 16:22, 39; 23:29). Miqueas lo usa para la ciudad de Safir, que sale en ''desnudez y vergüenza'' (Miq 1:11). Habacuc 3:9 lo aplica de forma llamativa al arco de Dios, que queda ''al descubierto'', despojado de su funda y listo para la batalla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6182', 'spa', 'masa, harina gruesa; la primera porción de masa amasada o harina ofrecida a Dios', 'Término de significado incierto, entendido tradicionalmente como masa o harina gruesa, que se refiere a la primera porción ofrecida a Dios. Números 15:20-21 ordena ofrecer «lo primero de vuestra masa» al Señor como contribución del primer procesamiento del grano en alimento. Nehemías 10:37 incluye «las primicias de nuestras masas» entre las ofrendas llevadas a los sacerdotes, y Ezequiel 44:30 asigna esta primicia a los sacerdotes. El término puede derivar de una raíz relacionada con artesas o lechos donde se amasaba, o representar harina de cebada o trigo en etapas tempranas de procesamiento. El contexto constante es la ofrenda de primicias del procesamiento del grano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6183', 'spa', 'nubes (posiblemente nubes densas y oscuras que ocultan la luz)', 'Isaías 5:30 advierte de una oscuridad venidera: «si se mira a la tierra, he aquí tinieblas y angustia, y la luz se oscurece por sus nubes». Este sustantivo poco frecuente se refiere a nubes, probablemente del tipo denso y pesado que bloquea el sol. Algunos eruditos proponen enmendar el texto, pero el hebreo transmitido dice «nubes». La imagen es apocalíptica: la luz tragada por una cobertura nubosa ominosa que simboliza juicio y tiniebla. El versículo cierra los oráculos de ay de Isaías con una visión de perdición creciente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6184', 'spa', 'Imponente, aterrador; generalmente referido a tiranos despiadados u opresores violentos.', 'Imponente, aterrador; generalmente referido a tiranos despiadados u opresores violentos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6185', 'spa', 'sin hijos, despojado; privado de descendencia, sin heredero ni descendientes', 'Adjetivo que significa sin hijos o despojado, denotando específicamente a quien carece de descendientes. Génesis 15:2 expresa la angustia de Abraham: «sigo sin hijos», temiendo morir sin heredero. Jeremías pronuncia juicio sobre Jeconías: «Inscribid a este hombre como sin hijos» (22:30), no literalmente sin hijos, sino dinásticamente, pues ninguno se sentaría en el trono de David. Levítico 20:20-21 declara que ciertas uniones prohibidas resultarán en quedar «sin hijos», morir sin descendencia como castigo divino. El término expresa la devastadora condición, en el antiguo Cercano Oriente, de no tener descendientes que perpetúen el nombre y la herencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6186a', 'spa', 'Ordenar, disponer, formar en orden de batalla, preparar una mesa o comparar en valor; fundamentalmente, colocar las cosas en su disposición correcta.', 'Ordenar, disponer, formar en orden de batalla, preparar una mesa o comparar en valor; fundamentalmente, colocar las cosas en su disposición correcta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6186b', 'spa', 'Valuar, tasar (Hifil) — valoración sacerdotal de personas o bienes dedicados a YHWH.', 'La conjugación Hifil de עָרַךְ se emplea como término técnico para la tasación monetaria sacerdotal. En la legislación levítica de Levítico 27, cuando una persona, animal o casa se dedica a YHWH mediante un voto, el sacerdote debe fijar su valor monetario según escalas prescritas. El sacerdote ''valúa'' a la persona (Lv 27:8, 12, 14), estableciendo lo que debe pagarse para redimir el objeto consagrado. Esta función de tasación pertenece exclusivamente al sacerdote, convirtiendo la forma Hifil en un término de administración sacro-económica. La única aparición fuera de Levítico es 2 Reyes 23:35, donde Joacim ''tasó la tierra'' para recaudar el tributo del faraón Necao, una apropiación secular del lenguaje de tributación cúltica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6187', 'spa', 'Valuación o valor tasado (estimación sacerdotal); disposición, hilera u orden; un par o igual en rango', 'Valuación o valor tasado (estimación sacerdotal); disposición, hilera u orden; un par o igual en rango');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6189', 'spa', 'Incircunciso — literalmente de personas; figuradamente de corazones, labios u oídos cerrados; del fruto prohibido', 'Incircunciso — literalmente de personas; figuradamente de corazones, labios u oídos cerrados; del fruto prohibido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6190', 'spa', 'Prepucio: el pliegue de piel que se remueve en la circuncisión; figuradamente, la ''cobertura'' del corazón o de los árboles frutales.', 'Prepucio: el pliegue de piel que se remueve en la circuncisión; figuradamente, la ''cobertura'' del corazón o de los árboles frutales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6191', 'spa', 'ser astuto, sagaz o prudente; actuar con astucia o discernimiento', 'Verbo que abarca el territorio moralmente ambiguo entre la sabiduria y la astucia. En 1 S 23:22, Saul advierte que David ''es sumamente astuto,'' con un matiz negativo y amenazante. Sin embargo, en Proverbios la misma raiz adquiere coloracion positiva: el ingenuo ''se hace prudente'' mediante la correccion (Pr 19:25), y atender la reprension vuelve sagaz a la persona (Pr 15:5). En Sal 83:3, los enemigos ''traman astutamente sus planes'' contra el pueblo de Dios. El espanol distingue naturalmente entre ''astuto'' y ''prudente,'' revelando la doble valencia moral que hace tan rico este termino segun su contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6192', 'spa', 'amontonarse, apilarse (Nifal, dicho del agua u otras sustancias)', 'Éxodo 15:8 celebra el milagro del Mar Rojo: «Se amontonaron las aguas... las corrientes se levantaron como un montón». Este verbo en Nifal describe el agua apilándose verticalmente, desafiando la gravedad cuando Dios sopla con su aliento. Lenguas cognadas (sabeo, árabe, arameo, siríaco) comparten raíces relacionadas con montones, diques y pilas. La imagen es de agua formando un muro o montículo, abriendo un camino a través del mar. Es una inversión milagrosa del flujo natural del agua, donde lo fluido se comporta como sólido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6193', 'spa', 'astucia, sagacidad torcida; la habilidad intelectual empleada con fines engañosos o egoístas', 'Job 5:13 declara que Dios «atrapa a los sabios en su propia astucia», versículo citado por Pablo en 1 Corintios 3:19. Este sustantivo designa la sagacidad o el ingenio calculador de quienes se creen demasiado astutos para ser descubiertos. La raíz está emparentada con עָרְמָה (prudencia, astucia) y sugiere inteligencia aplicada con fines manipuladores. El contexto de Job es irónico: la habilidad humana se convierte en trampa cuando Dios interviene. Es sabiduría desprovista de rectitud, ingenio sin temor de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6194', 'spa', 'Montón o pila, usado para designar acumulaciones de grano, escombros o ruinas', 'Designa un montículo formado por acumulación, ya sea de grano cosechado, escombros o edificios destruidos. En Rut 3:7, Booz se acuesta junto al montón de grano después de aventar, una escena rica en imágenes de cosecha. Hageo 2:16 emplea la palabra para una pila de grano que defrauda las expectativas. En Nehemías 3:34 y Jeremías 50:26 el sentido se desplaza hacia montones de escombros y ruinas, evocando una masa informe amontonada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6195', 'spa', 'astucia, sagacidad o prudencia; habilidad aplicada de forma engañosa o sabia segun el contexto', 'Forma nominal de la raiz que significa ''ser astuto,'' con la misma doble carga moral que su contraparte verbal. En Ex 21:14 describe la premeditacion letal: matar ''con astucia.'' En Jos 9:4, los gabaonitas actuan ''con astucia'' para engañar a Israel. No obstante, Proverbios recupera el termino en sentido positivo: la sabiduria ofrece ''prudencia a los simples'' (Pr 1:4), y la Sabiduria personificada declara ''yo habito con la prudencia'' (Pr 8:12). El contexto determina si esta cualidad es vicio o virtud, tal como el espanol diferencia entre ''astucia'' y ''prudencia.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6197', 'spa', 'Erán, nombre propio de un descendiente de Efraín (Números 26:36); posible variante textual de Edén', 'Erán aparece en Números 26:36 como descendiente de Efraín y ancestro del clan eranita. Sin embargo, el texto samaritano y algunos manuscritos leen «Edén», y la versión griega registra Εδεν, lo que sugiere variación textual. El nombre podría ser una variante escribal o una forma alternativa genuina. Fuera de esta referencia censal, Erán es desconocido. El censo del desierto preserva la estructura de clanes de Efraín, y ya sea Erán o Edén la lectura original, el nombre representa un linaje legítimo dentro de la tribu de José.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6198', 'spa', 'el eranita, gentilicio colectivo del clan descendiente de Erán (Números 26:36)', 'Números 26:36 menciona a «los eranitas» como el clan descendiente de Erán (o Edén, según variantes textuales) dentro de la tribu de Efraín. Esta forma gentilicia, usada con el artículo definido, designa al grupo familiar de manera colectiva. El texto samaritano y los manuscritos griegos reflejan «edenita», coherente con la variante del nombre del ancestro. Independientemente de la grafía, los eranitas constituyen uno de los clanes efrainitas contabilizados en el censo del desierto, con derecho a una porción de la herencia territorial al oeste del Jordán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6199', 'spa', 'el despojado, el desnudo, aquel que ha quedado desprovisto de todo recurso y dignidad', 'El Salmo 102:17 habla de que Dios atiende «la oración del despojado», usando este adjetivo sustantivado para describir a alguien completamente desprovisto de recursos y dignidad. La raíz transmite la idea de desnudez, desamparo y privación total. En el mundo antiguo, el despojado carecía de tierra, familia y posición social: era absolutamente vulnerable. El salmista, clamando desde la aflicción profunda, se identifica con esta condición. No obstante, el salmo afirma que Dios no desprecia su oración; hay esperanza aun para el más desamparado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6200', 'spa', 'el aroerita, gentilicio que designa a alguien procedente de Aroer (1 Crónicas 11:44)', 'Primera Crónicas 11:44 incluye a «el aroerita» entre los valientes de David. Este gentilicio identifica a alguien oriundo de Aroer, topónimo que aparece varias veces en las Escrituras, referido generalmente a una ciudad moabita sobre el río Arnón. El término señala el lugar de origen o la identidad de clan del guerrero. Los manuscritos griegos transliteran el nombre con variaciones menores. Los valientes de David provenían de regiones diversas, y este aroerita representa uno de esos orígenes geográficos. Se le conoce solo por su procedencia, pero su inclusión entre la élite guerrera honra a su ciudad natal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6202', 'spa', 'Quebrar la cerviz (de un animal); derribar o destruir (altares).', 'El verbo עָרַף es un denominativo de עֹרֶף (''cerviz, nuca'') y significa literalmente quebrar el cuello de un animal. Aparece en dos contextos rituales: el primogénito de asno no redimido cuyo cuello debe quebrarse (Ex 13:13; 34:20), y la becerra cuyo cuello se quiebra en el rito por homicidio sin resolver de Dt 21:4, 6. Isaías 66:3 compara el sacrificio ilícito con quien ''quiebra el cuello a un perro''. En una extensión profética única, Oseas emplea la imagen figuradamente: Dios ''derribará'' sus altares (Os 10:2), trasladando la violenta acción de desnucar al ámbito de la destrucción de objetos cúlticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6203', 'spa', 'Nuca, cerviz: endurecida en resistencia obstinada; vuelta en huida del enemigo; la nuca literal', 'Nuca, cerviz: endurecida en resistencia obstinada; vuelta en huida del enemigo; la nuca literal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6205', 'spa', 'Oscuridad densa o nube espesa, especialmente la tiniebla impenetrable que envuelve la presencia teofánica de Dios', 'El ʿărāphel es la oscuridad profunda e impenetrable que rodea a Dios cuando se acerca: la nube espesa que cubría el Sinaí (Éx 20:21; Dt 4:11; 5:22), las densas tinieblas en que Salomón declara que Dios ha decidido habitar (1 R 8:12) y la lobreguez bajo los pies de Yahveh en los salmos teofánicos (2 S 22:10; Sal 18:9). Se distingue de la nube ordinaria (ʿānān) pero se empareja con ella, sugiriendo un estrato más denso y sobrecogedor. Job 38:9 envuelve poéticamente el mar primigenio en ʿărāphel como pañal. Los profetas extienden la imagen al juicio: Sofonías designa el Día del Señor como día de nube y ʿărāphel (Sof 1:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6206', 'spa', 'Temblar de terror o pavor; causativamente aterrorizar o infundir temor; pasivamente ser temido o imponente', 'Este verbo capta ambas caras del pavor: el terror sentido y el terror infligido. Moisés dice a Israel ''no os aterroricéis'' ante las naciones (Dt 7:21), mientras que Dios se levanta ''para aterrorizar la tierra'' (Is 2:19). La raíz se mueve así fluidamente entre sujeto y objeto del temor. En su registro más elevado, las formas Hifil y Nifal describen el santo temor reverencial que rodea a Dios mismo: ''grandemente temido en la asamblea de los santos'' (Sal 89:7). El español distingue bien: ''aterroricéis'' para el pavor intransitivo, ''aterrorizar'' para el causativo y ''temido'' para el pasivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6209', 'spa', 'desnudar por completo, arrasar; exponer cimientos demoliendo totalmente, o despojarse de vestiduras', 'Verbo que significa desnudar o dejar completamente al descubierto, aplicado tanto a la demolición de edificios como al despojo de vestiduras. En Isaías 23:13, Asiria arrasa los palacios de Tiro dejando al descubierto sus cimientos. Isaías 32:11 ordena a las mujeres complacientes despojarse de sus ropas en señal de duelo. Jeremías 51:58 intensifica el sentido mediante repetición: los muros de Babilonia serán «completamente demolidos», arrasados hasta el suelo. El verbo transmite la idea de una exposición total o un desmantelamiento absoluto, ya sea de construcciones o de vestiduras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6210', 'spa', 'Lecho o cama para dormir, reclinarse o descansar; desde una cama corriente hasta un diván lujoso o lecho de enfermo', 'Designa un mueble para acostarse, ya sea para el descanso nocturno, el banquete suntuoso o la convalecencia. En Amós 3:12 y 6:4, el profeta lo empareja con mittah para condenar a los ricos ociosos que se recuestan en divanes ornamentados. En Deuteronomio 3:11, el famoso ʿereś de hierro de Og puede referirse a un enorme armazón de cama o incluso a un sarcófago funerario. Los Salmos emplean la misma palabra tanto para el lecho empapado de lágrimas del afligido (Sal 6:6) como para el lecho de enfermo donde el Señor sustenta al doliente (Sal 41:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6211a', 'spa', 'Polilla; insecto que devora tejidos, usado figuradamente para la destruccion lenta e insidiosa y la fragilidad humana ante Dios', 'Se refiere a la polilla o su larva, el diminuto insecto cuyas larvas consumen silenciosamente prendas y material organico. En las Escrituras se convierte en imagen vivida de destruccion callada e implacable. Oseas la empareja con la carcoma para describir el juicio gradual de Dios sobre Efrain (Os 5:12), mientras que Job la emplea para subrayar la fragilidad humana, aplastado ''como vestido que la polilla roe'' (Job 13:28). Isaias advierte dos veces que los opresores seran consumidos como ropa apolillada (Is 50:9; 51:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6211b', 'spa', 'hierba, pasto; vegetacion del campo que sirve de forraje para animales de pastoreo', 'Sustantivo arameo que aparece exclusivamente en las secciones arameas de Daniel, siempre en el contexto de la humillacion de Nabucodonosor. Cuando el rey es expulsado de la sociedad humana, come ''hierba como los bueyes'' (Dn 4:25, 32, 33), reducida su dieta real a simple pasto del campo. El termino aparece en el decreto celestial (Dn 4:15) y nuevamente cuando el juicio es relatado a Belsasar (Dn 5:21). El espanol ''hierba'' y el ingles ''grass'' lo traducen uniformemente como vegetacion silvestre, subrayando la degradacion total del rey desde los banquetes palaciegos hasta el forraje animal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6212', 'spa', 'Hierba, herbaje, pasto o vegetación verde; vida vegetal dada por Dios como alimento y símbolo de lo transitorio', 'Hierba, herbaje, pasto o vegetación verde; vida vegetal dada por Dios como alimento y símbolo de lo transitorio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6213', 'spa', 'hacer, realizar; ejecutar una acción o producir algo (formas conjugadas del Qal)', 'El verbo hebreo fundamental עָשָׂה en su conjugación Qal, que abarca el amplio rango semántico de ''hacer'' y ''realizar''. Estas ocurrencias particulares capturan formas conjugadas en primera y segunda persona: promesas de acción futura, mandatos y logros pasados. En Ezequiel 16, el verbo aparece repetidamente para describir tanto las obras de Israel como la respuesta de Dios, mientras que Jeremías 40:16 registra un compromiso de acción. En español se traduce con flexibilidad como haré, hagas e hiciste, reflejando la adaptabilidad del verbo a través de tiempos y personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6213a', 'spa', 'hacer, realizar, obrar; fabricar, construir; ser hecho (Nifal); producir, dar fruto; trabajar, laborar', 'El gran verbo hebreo de acción universal, con más de 2.600 ocurrencias. Equivalente a «hacer» en toda su amplitud, cubre desde la creación divina de los cielos hasta el trabajo del agricultor en su campo. Su espectro semántico se extiende de lo divino — «tu Hacedor» como título de Dios (Job 4:17) — a lo agrícola, donde una viña «produce» uvas silvestres (Is 5:2). El Nifal pasivo permite que los acontecimientos simplemente «sean hechos» sin nombrar agente, construcción favorecida en contextos legales y narrativos. El árabe conserva una escisión similar entre faʿala (hacer) y ṣanaʿa (fabricar), sugiriendo que el hebreo fusionó dos raíces protosemíticas en un solo verbo comodín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6213b', 'spa', 'apretar, oprimir, manosear (pechos); tocar sexualmente', 'Esta raíz secundaria del verbo común ''hacer'' adquiere un significado físico específico: apretar u oprimir, particularmente en un contexto sexual. Aparece exclusivamente en Ezequiel 23, donde el profeta usa lenguaje gráfico para describir el adulterio espiritual de Jerusalén y Samaria como inmoralidad sexual literal. El verbo describe el manoseo de los pechos de las jóvenes, simbolizando las alianzas ilícitas de Israel con naciones extranjeras. La forma Piel intensifica la acción—manoseo repetido o forzoso. Esta imaginería contundente subraya la intimidad y la traición involucradas en la infidelidad al pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6214', 'spa', 'Asael: ''Dios ha hecho''; sobrino de David famoso por su velocidad, también levitas y una figura postexílica.', 'Asael: ''Dios ha hecho''; sobrino de David famoso por su velocidad, también levitas y una figura postexílica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6215', 'spa', 'Esaú — el hijo primogénito de Isaac y Rebeca, hermano gemelo de Jacob, ancestro y epónimo de los edomitas', 'Esaú — el hijo primogénito de Isaac y Rebeca, hermano gemelo de Jacob, ancestro y epónimo de los edomitas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6216', 'spa', 'opresor, el que extorsiona o defrauda mediante violencia o injusticia', 'Jeremías 22:3 ordena: «No hagáis agravio ni violencia al extranjero, al huérfano ni a la viuda, ni derraméis sangre inocente en este lugar, y librad al oprimido de mano del opresor.» Este sustantivo designa a quien oprime o extorsiona, abusando de su poder para defraudar y dañar a los vulnerables. Está emparentado con el más frecuente עֹשֵׁק (opresor, 21:12). El contexto es un oráculo profético dirigido al rey de Judá, exigiendo justicia y protección de los débiles. La falta de acción contra la opresión acarrea juicio divino sobre la casa real.');